/* Ngữ pháp HSK 1–6 (TOEIC Path tự soạn theo các điểm ngữ pháp của từng cấp). Pinyin tạo tự động bằng pypinyin. */
window.HSK_GRAMMAR = [{"lv":1,"id":"h1-shi","name":"Câu với 是 và trợ từ 的","zh":"是 / 的","use":"是 nối chủ ngữ với danh từ (A là B). 的 đứng giữa người/vật sở hữu và vật được sở hữu, hoặc giữa định ngữ và danh từ.","form":[["A + 是 + B","A là B; phủ định: A + 不是 + B"],["Người/vật + 的 + danh từ","我的书 = sách của tôi"]],"tips":["Với người thân, bạn bè, nơi thân thuộc thường bỏ 的: 我妈妈, 我们学校.","Tính từ không dùng 是: nói 我很忙, không nói 我是忙."],"eg":[["我是越南人。","wǒ shì yuènánrén.","Tôi là người Việt Nam.",["我","是","越南人","。"]],["这是我的手机。","zhè shì wǒ de shǒujī.","Đây là điện thoại của tôi.",["这","是","我","的","手机","。"]],["他不是老师，是学生。","tā búshì lǎoshī, shì xuésheng.","Anh ấy không phải giáo viên, là học sinh.",["他","不是","老师","，","是","学生","。"]]],"fix":["我是很高兴。","我很高兴。","Trước tính từ dùng 很, không dùng 是.","wǒ hěn gāoxìng."],"ex":[{"q":"这___我朋友的书。","p":"zhè shì wǒ péngyou de shū.","o":["是","有","在","的"],"a":0,"e":"A là B dùng 是."},{"q":"那是老师___电脑。","p":"nà shì lǎoshī de diànnǎo.","o":["的","是","了","吗"],"a":0,"e":"Sở hữu: 老师的电脑."},{"q":"她___中国人，是越南人。","p":"tā búshì Zhōngguó rén, shì yuènánrén.","o":["不是","没","没是","不有"],"a":0,"e":"Phủ định của 是 là 不是."},{"q":"我___很忙。","p":"wǒ jīntiān hěn máng.","o":["今天","是","的","有"],"a":0,"e":"Tính từ làm vị ngữ không cần 是; 今天 chỉ thời gian."}]},{"lv":1,"id":"h1-hoi","name":"Câu hỏi với 吗, 呢 và đại từ nghi vấn","zh":"吗 / 呢 / 什么 / 谁 / 哪儿","use":"Thêm 吗 vào cuối câu trần thuật để hỏi có/không. Dùng đại từ nghi vấn (什么, 谁, 哪, 哪儿, 几, 多少, 怎么) đặt đúng vị trí của thông tin cần hỏi, không thêm 吗.","form":[["Câu trần thuật + 吗？","hỏi có/không"],["Danh từ / chủ ngữ + 呢？","Còn … thì sao?"],["Giữ trật tự câu, thay chỗ cần hỏi bằng 谁/什么/哪儿","你去哪儿？"]],"tips":["Câu đã có 什么, 谁, 哪儿… thì không thêm 吗.","几 hỏi số nhỏ (thường dưới 10, có lượng từ); 多少 hỏi số bất kỳ."],"eg":[["你是老师吗？","nǐ shì lǎoshī ma?","Bạn là giáo viên à?",["你","是","老师","吗","？"]],["我喝茶，你呢？","wǒ hēchá, nǐ ne?","Tôi uống trà, còn bạn?",["我","喝茶","，","你","呢","？"]],["你叫什么名字？","nǐ jiào shénme míngzi?","Bạn tên là gì?",["你","叫","什么","名字","？"]],["他去哪儿？","tā qù nǎr?","Anh ấy đi đâu?",["他","去","哪儿","？"]]],"fix":["你去哪儿吗？","你去哪儿？","Câu đã có 哪儿 thì không thêm 吗.","nǐ qù nǎr?"],"ex":[{"q":"你喜欢喝咖啡___？","p":"nǐ xǐhuan hēkāfēi ma?","o":["吗","呢","什么","谁"],"a":0,"e":"Câu hỏi có/không dùng 吗."},{"q":"这是___的书？","p":"zhè shì shuí de shū?","o":["谁","哪","几","吗"],"a":0,"e":"Hỏi người sở hữu dùng 谁."},{"q":"你家有___口人？","p":"nǐjiā yǒu jǐkǒu rén?","o":["几","多","什么","哪"],"a":0,"e":"Hỏi số người trong nhà: 几口人."},{"q":"我很好，你___？","p":"wǒ hěn hǎo, nǐ ne?","o":["呢","吗","什么","的"],"a":0,"e":"Hỏi ngược lại người nghe dùng 呢."}]},{"lv":1,"id":"h1-bu-mei","name":"Phủ định với 不 và 没","zh":"不 / 没(有)","use":"不 phủ định hiện tại, tương lai, thói quen, ý muốn và tính từ. 没(有) phủ định việc đã xảy ra và phủ định 有.","form":[["不 + động từ / tính từ","我不去 / 不贵"],["没(有) + động từ","我没去 (đã không đi)"],["没有 + danh từ","我没有钱 (không có)"]],"tips":["有 chỉ đi với 没, không nói 不有.","Câu phủ định với 没 thì bỏ 了: 我没吃饭, không nói 我没吃了饭."],"eg":[["我明天不上班。","wǒ míngtiān bù shàngbān.","Ngày mai tôi không đi làm.",["我","明天","不","上班","。"]],["昨天他没来。","zuótiān tā méilái.","Hôm qua anh ấy không đến.",["昨天","他","没来","。"]],["我没有哥哥。","wǒ méiyǒu gēge.","Tôi không có anh trai.",["我","没有","哥哥","。"]]],"fix":["我不有时间。","我没有时间。","有 phủ định bằng 没.","wǒ méiyǒu shíjiān."],"ex":[{"q":"我___有中文书。","p":"wǒ méiyǒu zhōng wénshū.","o":["没","不","是","很"],"a":0,"e":"有 dùng 没."},{"q":"昨天我___去学校。","p":"zuótiān wǒ méi qù xuéxiào.","o":["没","不","别","是"],"a":0,"e":"Việc trong quá khứ dùng 没."},{"q":"这个菜___好吃。","p":"zhège cài bù hǎochī.","o":["不","没","没有","是"],"a":0,"e":"Phủ định tính từ dùng 不."},{"q":"我明天___去商店。","p":"wǒ míngtiān bùqù shāngdiàn.","o":["不","没","没有","了"],"a":0,"e":"Ý định tương lai dùng 不."}]},{"lv":1,"id":"h1-ye-dou","name":"Phó từ 也 và 都","zh":"也 / 都","use":"也 = cũng, 都 = đều. Cả hai là phó từ, luôn đứng sau chủ ngữ và trước động từ/tính từ. Khi dùng cùng nhau thì 也 đứng trước 都.","form":[["S + 也 + V/adj","我也是学生"],["S (số nhiều) + 都 + V/adj","我们都是学生"],["S + 也都 + V","他们也都去"]],"tips":["Không đặt 也 ở đầu câu hay cuối câu như \"cũng\" trong tiếng Việt."],"eg":[["我也喜欢喝茶。","wǒ yě xǐhuan hēchá.","Tôi cũng thích uống trà.",["我","也","喜欢","喝茶","。"]],["我们都是越南人。","wǒmen dōu shì yuènánrén.","Chúng tôi đều là người Việt Nam.",["我们","都","是","越南人","。"]],["他们也都认识王老师。","tāmen yě dōu rènshi wánglǎoshī.","Họ cũng đều quen thầy Vương.",["他们","也","都","认识","王老师","。"]]],"fix":["也我是学生。","我也是学生。","也 đứng sau chủ ngữ.","wǒ yě shì xuésheng."],"ex":[{"q":"我是老师，他___是老师。","p":"wǒ shì lǎoshī, tā yě shì lǎoshī.","o":["也","都","和","很"],"a":0,"e":"Hai người, \"cũng\": 也."},{"q":"我们___喜欢吃饺子。","p":"wǒmen dōu xǐhuan chījiǎozi.","o":["都","也都是","和","还"],"a":0,"e":"Chủ ngữ số nhiều, \"đều\": 都."},{"q":"他们___都是我的朋友。","p":"tāmen yě dōu shì wǒ de péngyou.","o":["也","都","和","很"],"a":0,"e":"也 đứng trước 都."},{"q":"爸爸、妈妈___在家。","p":"bàba māma dōu zàijiā.","o":["都","和","也是","很"],"a":0,"e":"Cả hai người đều ở nhà: 都."}]},{"lv":1,"id":"h1-he","name":"Liên từ 和 nối danh từ","zh":"和 / 跟","use":"和 nối hai danh từ hoặc đại từ (A và B). Không dùng 和 để nối hai động từ hay hai câu như chữ \"và\" trong tiếng Việt.","form":[["A + 和 + B","我和他 / 爸爸和妈妈"],["Ba thứ trở lên: A、B 和 C","茶、咖啡和牛奶"]],"tips":["Nối hai hành động thì không dùng 和: nói 我吃饭，然后看电视 hoặc 我吃饭、看电视."],"eg":[["我和我朋友都是学生。","wǒ hé wǒ péngyou dōu shì xuésheng.","Tôi và bạn tôi đều là học sinh.",["我","和","我","朋友","都","是","学生","。"]],["我喜欢苹果和香蕉。","wǒ xǐhuan píngguǒ hé xiāngjiāo.","Tôi thích táo và chuối.",["我","喜欢","苹果","和","香蕉","。"]],["桌子上有书、手机和杯子。","zhuōzi shàng yǒu shū shǒujī hé bēizi.","Trên bàn có sách, điện thoại và cốc.",["桌子","上","有","书","、","手机","和","杯子","。"]]],"fix":["我吃饭和看电视。","我吃饭，看电视。","和 không nối hai động từ.","wǒ chīfàn, kàndiànshì."],"ex":[{"q":"我___妹妹去商店。","p":"wǒ hé mèimei qù shāngdiàn.","o":["和","也","都","是"],"a":0,"e":"Nối hai người: 和."},{"q":"我喜欢茶___咖啡。","p":"wǒ xǐhuan chá hé kāfēi.","o":["和","也","都","很"],"a":0,"e":"Nối hai danh từ: 和."},{"q":"爸爸___妈妈都在医院工作。","p":"bàba hé māma dōu zài yīyuàn gōngzuò.","o":["和","也","还","是"],"a":0,"e":"A 和 B."},{"q":"我买了面包、牛奶___鸡蛋。","p":"wǒ mǎi le miànbāo niúnǎi hé jīdàn.","o":["和","也","都","了"],"a":0,"e":"Cuối liệt kê: 和."}]},{"lv":1,"id":"h1-you-zai","name":"有 và 在: có, ở đâu","zh":"有 / 在","use":"在 cho biết người/vật ở đâu. 有 cho biết ở một nơi có cái gì, hoặc ai đó sở hữu cái gì. 在 đặt trước động từ còn nghĩa là \"đang\".","form":[["Người/vật + 在 + nơi chốn","我在家"],["Nơi chốn + 有 + người/vật","桌子上有一本书"],["在 + nơi chốn + động từ","我在学校学习"]],"tips":["Nơi chốn đứng đầu câu thì dùng 有; người/vật cụ thể đứng đầu thì dùng 在."],"eg":[["妈妈在医院工作。","māma zài yīyuàn gōngzuò.","Mẹ làm việc ở bệnh viện.",["妈妈","在","医院","工作","。"]],["学校旁边有一个饭店。","xuéxiào pángbiān yǒu yígè fàndiàn.","Cạnh trường có một nhà hàng.",["学校","旁边","有","一个","饭店","。"]],["你的手机在桌子上。","nǐ de shǒujī zài zhuōzi shàng.","Điện thoại của bạn ở trên bàn.",["你","的","手机","在","桌子","上","。"]]],"fix":["我在学校学习在。","我在学校学习。","在 + nơi chốn đứng trước động từ.","wǒ zài xuéxiào xuéxí."],"ex":[{"q":"我的书___椅子下面。","p":"wǒ de shū zài yǐzi xiàmiàn.","o":["在","有","是","去"],"a":0,"e":"Vật cụ thể + 在 + nơi chốn."},{"q":"桌子上___三个杯子。","p":"zhuōzi shàng yǒu sāngè bēizi.","o":["有","在","是","的"],"a":0,"e":"Nơi chốn + 有 + vật."},{"q":"他___北京工作。","p":"tā zài běijīng gōngzuò.","o":["在","有","是","到"],"a":0,"e":"在 + nơi chốn + động từ."},{"q":"你家___狗吗？","p":"nǐjiā yǒu gǒu ma?","o":["有","在","是","没"],"a":0,"e":"Hỏi sở hữu dùng 有."}]},{"lv":1,"id":"h1-luongtu","name":"Lượng từ và 这, 那","zh":"个 / 本 / 杯 / 口 / 块","use":"Giữa số đếm (hoặc 这, 那, 几) và danh từ phải có lượng từ. Mỗi nhóm danh từ đi với lượng từ riêng.","form":[["Số / 这 / 那 / 几 + lượng từ + danh từ","三本书, 这个人"],["两 + lượng từ","số 2 trước lượng từ dùng 两, không dùng 二"]],"tips":["个 dùng rộng nhất; 本 sách vở; 杯 cốc; 口 người trong gia đình; 块 đồng tiền, miếng; 件 quần áo, sự việc; 张 vật mỏng phẳng."],"eg":[["我有两个弟弟。","wǒ yǒu liǎnggè dìdi.","Tôi có hai em trai.",["我","有","两个","弟弟","。"]],["请给我一杯水。","qǐng gěi wǒ yībēi shuǐ.","Cho tôi một cốc nước.",["请","给","我","一杯","水","。"]],["这本书多少钱？","zhè běnshū duōshǎoqián?","Quyển sách này bao nhiêu tiền?",["这","本书","多少钱","？"]]],"fix":["我有二个朋友。","我有两个朋友。","Trước lượng từ dùng 两.","wǒ yǒu liǎnggè péngyou."],"ex":[{"q":"我想买三___书。","p":"wǒ xiǎng mǎi sān běnshū.","o":["本","个","杯","口"],"a":0,"e":"Sách dùng 本."},{"q":"我家有四___人。","p":"wǒjiā yǒu sìkǒu rén.","o":["口","本","件","张"],"a":0,"e":"Người trong gia đình dùng 口."},{"q":"我要___杯咖啡。","p":"wǒyào liǎngbēi kāfēi.","o":["两","二","第二","双"],"a":0,"e":"Số 2 trước lượng từ dùng 两."},{"q":"___个人是我的老师。","p":"nàge rén shì wǒ de lǎoshī.","o":["那","哪","那儿","谁"],"a":0,"e":"Chỉ người ở xa dùng 那个."}]},{"lv":1,"id":"h1-shijian","name":"Nói giờ, ngày, tháng, thứ","zh":"点 / 分 / 半 / 号 / 星期","use":"Giờ: số + 点 + số + 分, rưỡi dùng 半. Ngày tháng nói từ lớn đến nhỏ: năm 年 → tháng 月 → ngày 号/日 → thứ 星期.","form":[["số + 点 (+ số + 分)","八点十分, 九点半"],["年 + 月 + 号 + 星期","2026年11月22号星期日"],["Hỏi: 几点？/ 几号？/ 星期几？","今天几号？"]],"tips":["Số năm đọc từng chữ số: 2026年 = èr líng èr liù nián.","2 giờ nói 两点, không nói 二点."],"eg":[["现在两点半。","xiànzài liǎngdiǎn bàn.","Bây giờ là hai giờ rưỡi.",["现在","两点","半","。"]],["今天十一月二十二号，星期日。","jīntiān shíyīyuè èrshíèrhào, Xīngqīrì.","Hôm nay ngày 22 tháng 11, chủ nhật.",["今天","十一月","二十二号","，","星期日","。"]],["我们八点十五分上课。","wǒmen bādiǎn shíwǔfēn shàngkè.","Chúng tôi vào học lúc tám giờ mười lăm.",["我们","八点","十五分","上课","。"]]],"fix":["现在二点。","现在两点。","2 giờ dùng 两点.","xiànzài liǎngdiǎn."],"ex":[{"q":"现在___点了？","p":"xiànzài jǐdiǎn le?","o":["几","多少","什么","哪"],"a":0,"e":"Hỏi giờ: 几点."},{"q":"今天星期___？","p":"jīntiān xīngqī jǐ?","o":["几","什么","多少","哪"],"a":0,"e":"Hỏi thứ: 星期几."},{"q":"我七点___起床。","p":"wǒ qīdiǎn bàn qǐchuáng.","o":["半","一半","多","个"],"a":0,"e":"Bảy giờ rưỡi: 七点半."},{"q":"明天是十二月一___。","p":"míngtiān shì shíèryuè yīhào.","o":["号","点","个","年"],"a":0,"e":"Ngày trong tháng: 号."}]},{"lv":1,"id":"h1-thoigian","name":"Vị trí từ chỉ thời gian và nơi chốn","zh":"时间词","use":"Trong tiếng Trung, thời gian và nơi chốn đứng TRƯỚC động từ, khác tiếng Việt. Thứ tự thường gặp: chủ ngữ + thời gian + nơi chốn + động từ + tân ngữ.","form":[["S + thời gian + 在 + nơi chốn + V + O","我明天在家看书"],["Thời gian + S + V + O","明天我去北京 (cũng đúng)"]],"tips":["Không đặt thời gian ở cuối câu như tiếng Việt: không nói 我去北京明天.","Thời gian đọc từ lớn đến nhỏ: 2026年11月22号上午九点."],"eg":[["我每天早上七点起床。","wǒ měitiān zǎoshang qīdiǎn qǐchuáng.","Mỗi sáng tôi dậy lúc bảy giờ.",["我","每天","早上","七点","起床","。"]],["他下午在图书馆看书。","tā xiàwǔ zài túshūguǎn kànshū.","Buổi chiều anh ấy đọc sách ở thư viện.",["他","下午","在","图书馆","看书","。"]],["我们星期六去看电影。","wǒmen xīngqīliù qù kàn diànyǐng.","Thứ bảy chúng tôi đi xem phim.",["我们","星期六","去","看","电影","。"]]],"fix":["我吃饭在饭店。","我在饭店吃饭。","Nơi chốn đặt trước động từ.","wǒ zài fàndiàn chīfàn."],"ex":[{"q":"我___去商店。","p":"wǒ míngtiān qù shāngdiàn.","o":["明天","在明天","明天的","是明天"],"a":0,"e":"Từ thời gian đứng trước động từ."},{"q":"他晚上___家看电视。","p":"tā wǎnshang zàijiā kàndiànshì.","o":["在","有","是","去"],"a":0,"e":"在 + nơi chốn trước động từ."},{"q":"我们___点上课？","p":"wǒmen jǐdiǎn shàngkè?","o":["几","多少","什么","哪"],"a":0,"e":"Hỏi giờ dùng 几点."},{"q":"___我在家休息。","p":"jīntiān wǒ zàijiā xiūxi.","o":["今天","今天的","在今天","是今天"],"a":0,"e":"Thời gian có thể đứng đầu câu."}]},{"lv":1,"id":"h1-ba","name":"Gợi ý và đoán với 吧","zh":"吧","use":"吧 cuối câu dùng để rủ rê, gợi ý (…đi, …nhé), hoặc để đoán và chờ xác nhận (chắc là… nhỉ).","form":[["Câu đề nghị + 吧","我们走吧"],["Câu phỏng đoán + 吧？","你是学生吧？"]],"tips":["Khác 吗: câu với 吗 là hỏi thật, chưa biết; câu với 吧 là đoán, nghĩ là đúng rồi."],"eg":[["我们一起去吃饭吧！","wǒmen yīqǐ qù chīfàn ba!","Chúng mình cùng đi ăn cơm nhé!",["我们","一起","去","吃饭","吧","！"]],["你累了吧？休息一下吧。","nǐ lèi le ba? xiūxi yīxià ba.","Chắc bạn mệt rồi nhỉ? Nghỉ một chút đi.",["你","累","了","吧","？","休息","一下","吧","。"]],["他是你哥哥吧？","tā shì nǐ gēge ba?","Anh ấy là anh trai bạn phải không?",["他","是","你","哥哥","吧","？"]]],"fix":["我们去看电影吗！","我们去看电影吧！","Rủ rê dùng 吧.","wǒmen qù kàn diànyǐngba!"],"ex":[{"q":"天气很好，我们去公园___。","p":"tiānqì hěn hǎo, wǒmen qù gōngyuán ba.","o":["吧","吗","呢","的"],"a":0,"e":"Rủ rê: 吧."},{"q":"你是越南人___？我听你说话像越南人。","p":"nǐ shì yuènánrén ba? wǒ tīng nǐ shuōhuà xiàng yuènánrén.","o":["吧","呢","了","啊"],"a":0,"e":"Đoán: 吧."},{"q":"太晚了，你回家___。","p":"tàiwǎn le, nǐ huíjiāba.","o":["吧","吗","呢","过"],"a":0,"e":"Lời khuyên: 吧."},{"q":"你是新来的学生___？","p":"nǐ shì xīnlái de xuésheng ba?","o":["吧","呢","啊","么"],"a":0,"e":"Phỏng đoán chờ xác nhận."}]},{"lv":1,"id":"h1-nengyuan","name":"Động từ năng nguyện: 想, 要, 会, 能, 可以","zh":"想 / 要 / 会 / 能 / 可以","use":"Đứng trước động từ để thể hiện mong muốn, khả năng, sự cho phép. 想 muốn (nhẹ), 要 muốn/cần/sẽ, 会 biết làm (học mới biết) hoặc sẽ, 能 có thể (điều kiện, năng lực), 可以 được phép.","form":[["S + 想/要/会/能/可以 + V","我想喝茶"],["Phủ định: 不想 / 不会 / 不能 / 不可以","要 → 不想 (không muốn) hoặc 不用 (không cần)"]],"tips":["Kỹ năng học được (nói tiếng Trung, bơi, lái xe) dùng 会.","Hỏi xin phép dùng 可以吗: 我可以坐这儿吗？"],"eg":[["我想去中国旅游。","wǒ xiǎng qù Zhōngguó lǚyóu.","Tôi muốn đi du lịch Trung Quốc.",["我","想","去","中国","旅游","。"]],["你会说汉语吗？","nǐ huì shuō Hànyǔ ma?","Bạn biết nói tiếng Trung không?",["你","会","说","汉语","吗","？"]],["这儿可以拍照吗？","zhèr kěyǐ pāizhào ma?","Ở đây được chụp ảnh không?",["这儿","可以","拍照","吗","？"]]],"fix":["我会去明天。","我明天会去。","Thời gian trước động từ năng nguyện.","wǒ míngtiān huì qù."],"ex":[{"q":"我___游泳，我学过。","p":"wǒhuì yóuyǒng, wǒxuéguò.","o":["会","想","要","可以"],"a":0,"e":"Kỹ năng học được dùng 会."},{"q":"我很累，___回家休息。","p":"wǒ hěn lèi, xiǎng huíjiā xiūxi.","o":["想","会","能够","可能"],"a":0,"e":"Mong muốn dùng 想."},{"q":"老师，我___进来吗？","p":"lǎoshī, wǒ kěyǐ jìnlái ma?","o":["可以","会","想","要"],"a":0,"e":"Xin phép dùng 可以."},{"q":"你明天___来吗？我有事找你。","p":"nǐ míngtiān nénglái ma? wǒ yǒushì zhǎo nǐ.","o":["能","会说","可能","在"],"a":0,"e":"Hỏi có thể đến được không dùng 能."}]},{"lv":1,"id":"h1-zenme","name":"Hỏi cách thức và lý do: 怎么, 为什么, 怎么样","zh":"怎么 / 为什么 / 怎么样","use":"怎么 + V hỏi cách làm (làm thế nào). 为什么 hỏi lý do (tại sao). 怎么样 hỏi ý kiến, tình trạng (thế nào), thường đứng cuối câu.","form":[["S + 怎么 + V？","你怎么去学校？"],["S + 为什么 + V？","你为什么不来？"],["… + 怎么样？","这个菜怎么样？"]],"tips":["怎么 + V còn có nghĩa ngạc nhiên \"sao lại\": 你怎么来了？"],"eg":[["这个字怎么写？","zhège zì zěnme xiě?","Chữ này viết thế nào?",["这个","字","怎么","写","？"]],["你为什么学汉语？","nǐ wèishénme xué Hànyǔ?","Tại sao bạn học tiếng Trung?",["你","为什么","学","汉语","？"]],["我们明天去公园，怎么样？","wǒmen míngtiān qù gōngyuán, zěnmeyàng?","Mai chúng ta đi công viên, thế nào?",["我们","明天","去","公园","，","怎么样","？"]]],"fix":["你去学校怎么？","你怎么去学校？","怎么 đứng trước động từ.","nǐ zěnme qù xuéxiào?"],"ex":[{"q":"你___去北京？坐飞机还是坐火车？","p":"nǐ zěnme qù běijīng? zuòfēijī háishi zuòhuǒchē?","o":["怎么","为什么","怎么样","什么"],"a":0,"e":"Hỏi cách đi: 怎么."},{"q":"你___不吃饭？","p":"nǐ wèishénme bù chīfàn?","o":["为什么","怎么样","什么","哪"],"a":0,"e":"Hỏi lý do: 为什么."},{"q":"这件衣服___？","p":"zhèjiàn yīfu zěnmeyàng?","o":["怎么样","怎么","为什么","几"],"a":0,"e":"Hỏi ý kiến: 怎么样."},{"q":"\"饺子\"这两个字___读？","p":"\" jiǎozi \" zhè liǎnggè zì zěnme dú?","o":["怎么","为什么","怎么样","多少"],"a":0,"e":"Đọc thế nào: 怎么读."}]},{"lv":1,"id":"h1-le-hen","name":"Tính từ làm vị ngữ, 太…了 và 了 hoàn thành","zh":"很 / 太…了 / 了","use":"Tính từ làm vị ngữ thường có 很 đứng trước (很 có thể chỉ để câu cân đối). 太…了 = quá… (cảm thán). 了 sau động từ hoặc cuối câu cho biết việc đã xảy ra hoặc có thay đổi.","form":[["S + 很 + tính từ","天气很好"],["太 + tính từ + 了","太贵了"],["S + V + 了 + (số lượng) + O","我买了一本书"]],"tips":["Không dùng 了 với 是, 在 hay thói quen lặp lại."],"eg":[["今天很热。","jīntiān hěn rè.","Hôm nay rất nóng.",["今天","很","热","。"]],["这个菜太好吃了！","zhège cài tài hǎochī le!","Món này ngon quá!",["这个","菜","太","好吃","了","！"]],["我昨天买了一件衣服。","wǒ zuótiān mǎi le yījiàn yīfu.","Hôm qua tôi đã mua một cái áo.",["我","昨天","买","了","一件","衣服","。"]]],"fix":["今天天气太好。","今天天气太好了。","太 cảm thán đi với 了 cuối câu.","jīntiāntiānqì tàihǎole."],"ex":[{"q":"这件衣服太贵___！","p":"zhèjiàn yīfu tàiguì le!","o":["了","的","吗","呢"],"a":0,"e":"太…了."},{"q":"我昨天看___一个电影。","p":"wǒ zuótiān kàn le yígè diànyǐng.","o":["了","过","着","的"],"a":0,"e":"Việc đã xong: V + 了."},{"q":"他___高。","p":"tā hěn gāo.","o":["很","是","有","在"],"a":0,"e":"Tính từ vị ngữ thường có 很."},{"q":"下雨___，我们不去了。","p":"xiàyǔ le, wǒmen bùqù le.","o":["了","的","过","吗"],"a":0,"e":"了 cuối câu chỉ sự thay đổi."}]},{"lv":1,"id":"h1-yidianr","name":"一点儿 và 有点儿","zh":"一点儿 / 有点儿","use":"有点儿 + tính từ = hơi… (thường là điều không vừa ý). Tính từ + 一点儿 = …hơn một chút (so sánh, yêu cầu). 一点儿 + danh từ = một ít.","form":[["有点儿 + adj","有点儿贵 (hơi đắt)"],["adj + 一点儿","便宜一点儿 (rẻ hơn một chút)"],["V + 一点儿 + N","喝一点儿水"]],"tips":[],"eg":[["这件衣服有点儿大。","zhèjiàn yīfu yǒudiǎnr dà.","Cái áo này hơi rộng.",["这件","衣服","有点儿","大","。"]],["能便宜一点儿吗？","néng piányi yīdiǎnr ma?","Có thể rẻ hơn một chút không?",["能","便宜","一点儿","吗","？"]],["我会说一点儿汉语。","wǒhuì shuō yīdiǎnr Hànyǔ.","Tôi biết nói một chút tiếng Trung.",["我会","说","一点儿","汉语","。"]]],"fix":["这个菜一点儿辣。","这个菜有点儿辣。","\"Hơi cay\" dùng 有点儿 + adj.","zhège cài yǒudiǎnr là."],"ex":[{"q":"今天___冷。","p":"jīntiān yǒudiǎnr lěng.","o":["有点儿","一点儿","一些","一下"],"a":0,"e":"Hơi lạnh: 有点儿冷."},{"q":"请说慢___。","p":"qǐng shuō màn yīdiǎnr.","o":["一点儿","有点儿","一下儿","一些"],"a":0,"e":"Chậm hơn một chút: 慢一点儿."},{"q":"我想喝___水。","p":"wǒ xiǎng hē yīdiǎnr shuǐ.","o":["一点儿","有点儿","一下","多"],"a":0,"e":"Một ít nước: 一点儿水."},{"q":"这个苹果___贵，能便宜一点儿吗？","p":"zhège píngguǒ yǒudiǎnr guì, néng piányi yīdiǎnr ma?","o":["有点儿","一点儿","很多","一些"],"a":0,"e":"Hơi đắt: 有点儿贵."}]},{"lv":1,"id":"h1-bieyao","name":"Câu cầu khiến: 请, 别, 不要","zh":"请 / 别 / 不要","use":"请 + V = mời, xin vui lòng. 别 / 不要 + V = đừng… (khuyên ngăn, cấm).","form":[["请 + V","请坐, 请喝茶"],["别/不要 + V (+ 了)","别说话, 不要看手机"]],"tips":["别…了 dùng khi việc đang diễn ra và muốn dừng lại: 别哭了 (đừng khóc nữa)."],"eg":[["请进！请坐！","qǐng jìn! qǐng zuò!","Mời vào! Mời ngồi!",["请","进","！","请","坐","！"]],["上课的时候不要看手机。","shàngkè de shíhou bùyào kàn shǒujī.","Trong giờ học đừng xem điện thoại.",["上课","的","时候","不要","看","手机","。"]],["别担心，没事的。","bié dānxīn, méishì de.","Đừng lo, không sao đâu.",["别","担心","，","没事","的","。"]]],"fix":["你别不说话。","你别说话。","别 đã mang nghĩa phủ định.","nǐbié shuōhuà."],"ex":[{"q":"___喝茶。","p":"qǐng hēchá.","o":["请","别","很","都"],"a":0,"e":"Mời: 请."},{"q":"你生病了，___去上班了。","p":"nǐ shēngbìng le, biéqù shàngbān le.","o":["别","请","也","都"],"a":0,"e":"Khuyên đừng đi: 别."},{"q":"这里是医院，___打电话。","p":"zhèlǐ shì yīyuàn, bùyào dǎdiànhuà.","o":["不要","没","请","也"],"a":0,"e":"Cấm: 不要."},{"q":"___哭了，我们去吃饭吧。","p":"biékū le, wǒmen qù chīfàn ba.","o":["别","不","没","请"],"a":0,"e":"Đừng … nữa: 别…了."}]},{"lv":1,"id":"h1-gei","name":"Giới từ 给, 跟, 对","zh":"给 / 跟 / 对","use":"给 + người + V: làm gì cho/gửi tới ai. 跟 + người + (一起) + V: làm cùng ai. 对 + người/việc + adj/V: đối với.","form":[["S + 给 + người + V","我给妈妈打电话"],["S + 跟 + người + 一起 + V","我跟朋友一起去"],["S + 对 + người + adj","老师对我们很好"]],"tips":[],"eg":[["我给你打电话。","wǒ gěi nǐ dǎdiànhuà.","Tôi gọi điện cho bạn.",["我","给","你","打电话","。"]],["我想跟你一起学习。","wǒ xiǎng gēn nǐ yīqǐ xuéxí.","Tôi muốn học cùng bạn.",["我","想","跟","你","一起","学习","。"]],["他对学生很好。","tā duì xuésheng hěn hǎo.","Thầy ấy đối với học sinh rất tốt.",["他","对","学生","很","好","。"]]],"fix":["我打电话给你妈妈的。","我给你妈妈打电话。","给 + người đứng trước động từ.","wǒ gěi nǐ māma dǎdiànhuà."],"ex":[{"q":"我___妈妈买了一件衣服。","p":"wǒ gěi māma mǎi le yījiàn yīfu.","o":["给","跟","对","在"],"a":0,"e":"Mua cho mẹ: 给."},{"q":"你___谁一起去？","p":"nǐ gēn shuí yīqǐ qù?","o":["跟","给","对","在"],"a":0,"e":"Cùng ai: 跟…一起."},{"q":"喝茶___身体很好。","p":"hēchá duì shēntǐ hěn hǎo.","o":["对","给","跟","在"],"a":0,"e":"Tốt đối với sức khỏe: 对."},{"q":"晚上我___你发短信。","p":"wǎnshang wǒ gěi nǐ fāduǎnxìn.","o":["给","跟","对","从"],"a":0,"e":"Gửi tin nhắn cho bạn: 给."}]},{"lv":1,"id":"h1-cong-dao","name":"Từ… đến…: 从…到…, 离","zh":"从 / 到 / 离","use":"从 A 到 B = từ A đến B (thời gian hoặc nơi chốn). 离 = cách (khoảng cách hoặc thời gian còn lại).","form":[["从 + A + 到 + B","从八点到十二点"],["A + 离 + B + 远/近","学校离我家很近"]],"tips":["Hỏi khoảng cách: A 离 B 远吗？"],"eg":[["我从星期一到星期五上班。","wǒ cóng xīngqīyī dào xīngqīwǔ shàngbān.","Tôi đi làm từ thứ Hai đến thứ Sáu.",["我","从","星期一","到","星期五","上班","。"]],["从我家到学校要二十分钟。","cóng wǒjiā dào xuéxiào yào èrshífēnzhōng.","Từ nhà tôi đến trường mất hai mươi phút.",["从","我家","到","学校","要","二十分钟","。"]],["医院离这儿不远。","yīyuàn lí zhèr bùyuǎn.","Bệnh viện cách đây không xa.",["医院","离","这儿","不远","。"]]],"fix":["我家从学校很近。","我家离学校很近。","Khoảng cách dùng 离.","wǒjiā lí xuéxiào hěnjìn."],"ex":[{"q":"___北京到上海坐火车要几个小时？","p":"cóng běijīng dào shànghǎi zuòhuǒchē yào jǐgè xiǎoshí?","o":["从","离","在","到"],"a":0,"e":"Từ … đến …: 从."},{"q":"我家___学校很远。","p":"wǒjiā lí xuéxiào hěn yuǎn.","o":["离","从","在","到"],"a":0,"e":"Khoảng cách: 离."},{"q":"我们从九点___十一点上课。","p":"wǒmen cóng jiǔdiǎn dào shíyìdiǎn shàngkè.","o":["到","离","在","从"],"a":0,"e":"从…到…."},{"q":"商店___这儿近吗？","p":"shāngdiàn lí zhèr jìn ma?","o":["离","从","到","在"],"a":0,"e":"Hỏi khoảng cách: 离."}]},{"lv":1,"id":"h1-yixia","name":"Làm nhẹ động tác: V + 一下, động từ lặp lại","zh":"一下 / 看看","use":"V + 一下 hoặc lặp động từ (看看, 试试, 休息休息) làm cho hành động nhẹ nhàng, ngắn, lịch sự hơn (thử…, …một chút).","form":[["V + 一下","等一下, 看一下"],["VV / V一V (một âm tiết)","看看 / 看一看"],["ABAB (hai âm tiết)","休息休息, 介绍介绍"]],"tips":[],"eg":[["请等一下。","qǐngděngyíxià.","Xin đợi một chút.",["请等一下","。"]],["你看看这本书。","nǐ kànkàn zhè běnshū.","Bạn xem thử quyển sách này.",["你","看看","这","本书","。"]],["我给你介绍一下，这是我朋友。","wǒ gěi nǐ jièshào yīxià, zhè shì wǒ péngyou.","Để tôi giới thiệu một chút, đây là bạn tôi.",["我","给","你","介绍","一下","，","这","是","我","朋友","。"]]],"fix":["我们休休息息吧。","我们休息休息吧。","Động từ hai âm tiết lặp ABAB.","wǒmen xiūxi xiūxi ba."],"ex":[{"q":"请你等___，我马上来。","p":"qǐng nǐ děng yīxià, wǒ mǎshàng lái.","o":["一下","一点儿","有点儿","一些"],"a":0,"e":"Đợi một chút: 等一下."},{"q":"你___这件衣服，很漂亮。","p":"nǐ shìshì zhèjiàn yīfu, hěnpiàoliàng.","o":["试试","试一下下","试试看看","试了试了"],"a":0,"e":"Thử: 试试."},{"q":"我们___吧，太累了。","p":"wǒmen xiūxi xiūxi ba, tàilèi le.","o":["休息休息","休休息息","休息一休息","休一休息"],"a":0,"e":"ABAB: 休息休息."},{"q":"我来介绍___。","p":"wǒlái jièshào yīxià.","o":["一下","一点儿","有点儿","一次"],"a":0,"e":"介绍一下."}]},{"lv":1,"id":"h1-hai","name":"Còn, vẫn: 还 và 再","zh":"还 / 再","use":"还 = còn, vẫn (việc vẫn tiếp diễn, hoặc thêm vào). 再 = lại, nữa (lặp lại trong tương lai). 还没(有) + V = vẫn chưa.","form":[["S + 还 + V/adj","他还在睡觉"],["S + 还没(有) + V","我还没吃饭"],["S + 再 + V","明天再来"]],"tips":[],"eg":[["已经十点了，他还在睡觉。","yǐjīng shídiǎn le, tā hái zài shuìjiào.","Đã mười giờ rồi, anh ấy vẫn đang ngủ.",["已经","十点","了","，","他","还","在","睡觉","。"]],["我还想喝一杯茶。","wǒ hái xiǎng hēyībēi chá.","Tôi còn muốn uống thêm một cốc trà.",["我","还","想","喝一杯","茶","。"]],["请再说一次。","qǐng zàishuō yīcì.","Xin nói lại một lần nữa.",["请","再说","一次","。"]]],"fix":["我再没吃饭。","我还没吃饭。","Vẫn chưa: 还没.","wǒ hái méi chīfàn."],"ex":[{"q":"我___没去过中国。","p":"wǒ hái méi qùguò Zhōngguó.","o":["还","再","也","都"],"a":0,"e":"Vẫn chưa: 还没."},{"q":"今天太晚了，明天___来吧。","p":"jīntiān tàiwǎn le, míngtiān zàilái ba.","o":["再","还","也","就"],"a":0,"e":"Lặp lại trong tương lai: 再."},{"q":"你___要什么？","p":"nǐ háiyào shénme?","o":["还","再","就","都"],"a":0,"e":"Còn muốn gì nữa: 还."},{"q":"老师，请您___说一遍。","p":"lǎoshī, qǐng nín zàishuō yībiàn.","o":["再","还","也","才"],"a":0,"e":"Nói lại: 再说一遍."}]},{"lv":2,"id":"h2-guo","name":"Trải nghiệm với 过","zh":"V + 过","use":"过 đặt ngay sau động từ để nói đã từng làm việc gì (kinh nghiệm), không nhấn vào lúc nào.","form":[["S + V + 过 + O","我去过中国"],["Phủ định: S + 没(有) + V + 过 + O","我没吃过北京烤鸭"],["Câu hỏi: V + 过 + O + 吗 / V + 过 + O + 没有","你去过上海没有？"]],"tips":["Phủ định của 过 vẫn giữ 过, khác với 了 (没去 không có 了)."],"eg":[["我学过两年汉语。","wǒxuéguò liǎngnián Hànyǔ.","Tôi đã từng học tiếng Trung hai năm.",["我学过","两年","汉语","。"]],["你看过这个电影吗？","nǐ kànguò zhège diànyǐng ma?","Bạn đã từng xem phim này chưa?",["你","看过","这个","电影","吗","？"]],["我从来没坐过飞机。","wǒ cóngláiméi zuòguò fēijī.","Tôi chưa từng đi máy bay.",["我","从来没","坐过","飞机","。"]]],"fix":["我没去过了北京。","我没去过北京。","Không dùng 了 cùng 没…过.","wǒ méi qùguò běijīng."],"ex":[{"q":"我以前来___这儿。","p":"wǒ yǐqián láiguò zhèr.","o":["过","着","的","得"],"a":0,"e":"Kinh nghiệm: V + 过."},{"q":"他___吃过中国菜。","p":"tā méichīguò Zhōngguó cài.","o":["没","不","别","没有过"],"a":0,"e":"Phủ định: 没 + V + 过."},{"q":"你见过他___？","p":"nǐ jiàn guò tā ma?","o":["吗","呢","吧","的"],"a":0,"e":"Câu hỏi có/không."},{"q":"我从来没有___过日本。","p":"wǒ cónglái méiyǒu qùguò rìběn.","o":["去","去了","去着","要去"],"a":0,"e":"没有 + V + 过."}]},{"lv":2,"id":"h2-le-bianhua","name":"了 cuối câu: thay đổi trạng thái","zh":"…了 / 不…了 / 要…了","use":"了 cuối câu cho biết tình hình đã thay đổi so với trước (đã…, rồi). 不…了 = không… nữa. (快)要…了 = sắp… rồi.","form":[["S + adj/V + 了","天冷了 (trời lạnh rồi)"],["S + 不 + V + 了","我不去了 (tôi không đi nữa)"],["(快)要 + V + 了","快要下雨了"]],"tips":[],"eg":[["我饿了，我们吃饭吧。","wǒ è le, wǒmen chīfàn ba.","Tôi đói rồi, chúng ta ăn cơm đi.",["我","饿","了","，","我们","吃饭","吧","。"]],["他不喝咖啡了。","tā bù hēkāfēi le.","Anh ấy không uống cà phê nữa.",["他","不","喝咖啡","了","。"]],["快要考试了，我要好好复习。","kuàiyào kǎoshì le, wǒyào hǎohǎo fùxí.","Sắp thi rồi, tôi phải ôn bài cho tốt.",["快要","考试","了","，","我要","好好","复习","。"]]],"fix":["快要下雨。","快要下雨了。","快要 đi với 了 cuối câu.","kuàiyào xiàyǔ le."],"ex":[{"q":"冬天来了，天气冷___。","p":"dōngtiān lái le, tiānqì lěng le.","o":["了","过","着","的"],"a":0,"e":"Thay đổi: 了."},{"q":"我今天不舒服，不去学校___。","p":"wǒ jīntiān bù shūfu, bùqù xuéxiào le.","o":["了","过","的","着"],"a":0,"e":"Không… nữa: 不…了."},{"q":"火车快要开___，我们快走吧！","p":"huǒchē kuàiyào kāi le, wǒmen kuài zǒu ba!","o":["了","过","着","的"],"a":0,"e":"Sắp…: 快要…了."},{"q":"我女儿今年十岁___。","p":"wǒ nǚér jīnnián shísuì le.","o":["了","过","着","呢"],"a":0,"e":"Tuổi thay đổi: 了."}]},{"lv":2,"id":"h2-a-bu-a","name":"Câu hỏi chính phản: A不A","zh":"V不V / adj不adj / 有没有","use":"Ghép dạng khẳng định và phủ định của động từ/tính từ để hỏi có hay không. Câu đã có A不A thì không thêm 吗.","form":[["S + V不V + O？","你去不去？"],["S + adj不adj？","这个菜辣不辣？"],["S + 有没有 + N？ / V了没有？","你有没有哥哥？/ 你吃饭了没有？"]],"tips":["Động từ hai âm tiết có thể rút gọn: 喜不喜欢."],"eg":[["你是不是学生？","nǐ shìbúshì xuésheng?","Bạn có phải là học sinh không?",["你","是不是","学生","？"]],["这件衣服贵不贵？","zhèjiàn yīfu guìbùguì?","Cái áo này có đắt không?",["这件","衣服","贵不贵","？"]],["你喜不喜欢喝茶？","nǐ xǐbùxǐhuān hēchá?","Bạn có thích uống trà không?",["你","喜不喜欢","喝茶","？"]]],"fix":["你去不去吗？","你去不去？","A不A không thêm 吗.","nǐ qùbùqù?"],"ex":[{"q":"你明天来不___？","p":"nǐ míngtiān lái bùlái?","o":["来","去","是","吗"],"a":0,"e":"V不V: 来不来."},{"q":"这个菜好___好吃？","p":"zhège cài hǎobùhǎo chī?","o":["不","没","吗","很"],"a":0,"e":"好不好吃."},{"q":"你___有中文书？","p":"nǐ yǒuméiyǒu zhōng wénshū?","o":["有没","是不","会不","在不"],"a":0,"e":"有没有."},{"q":"你昨天去医院了___？","p":"nǐ zuótiān qù yīyuàn le méiyǒu?","o":["没有","不","吗呢","不是"],"a":0,"e":"V了没有."}]},{"lv":2,"id":"h2-zhengzai","name":"Hành động đang diễn ra: 正在…呢, 着","zh":"正在 / 在 / 着","use":"正在 / 在 / 正 + động từ (+ 呢) diễn tả hành động đang diễn ra. 着 sau động từ diễn tả trạng thái kéo dài (cửa mở, đang ngồi…).","form":[["S + 正在 + V + O + (呢)","他正在上课呢"],["S + V + 着","门开着 / 他穿着一件红衣服"],["Phủ định: 没(在) + V","我没在看电视"]],"tips":["Khi đang làm việc A thì việc B xảy ra: …的时候，正在…."],"eg":[["妈妈正在做饭呢。","māma zhèngzài zuòfàn ne.","Mẹ đang nấu cơm.",["妈妈","正在","做饭","呢","。"]],["他在打电话。","tā zài dǎdiànhuà.","Anh ấy đang gọi điện thoại.",["他","在","打电话","。"]],["门开着，请进。","ménkāi zhe, qǐng jìn.","Cửa đang mở, mời vào.",["门开","着","，","请","进","。"]]],"fix":["我正在看了书。","我正在看书。","正在 không đi với 了.","wǒ zhèngzài kànshū."],"ex":[{"q":"别说话，老师___上课呢。","p":"bié shuōhuà, lǎoshī zhèngzài shàngkè ne.","o":["正在","过","了","着"],"a":0,"e":"Hành động đang diễn ra."},{"q":"她穿___一件白衣服。","p":"tā chuānzhe yījiàn bái yīfu.","o":["着","过","了","在"],"a":0,"e":"Trạng thái kéo dài: V + 着."},{"q":"你给我打电话的时候，我___洗澡。","p":"nǐ gěi wǒ dǎdiànhuà de shíhou, wǒ zhèngzài xǐzǎo.","o":["正在","已经","刚才","就"],"a":0,"e":"Lúc đó đang làm việc khác."},{"q":"我们正在吃饭___。","p":"wǒmen zhèngzài chīfàn ne.","o":["呢","吗","吧","过"],"a":0,"e":"正在 … 呢."}]},{"lv":2,"id":"h2-zhe","name":"着 diễn tả trạng thái và cách thức","zh":"V + 着","use":"V + 着 diễn tả trạng thái đang duy trì (门开着). V1 + 着 + V2: làm V2 trong trạng thái V1 (坐着看书 = ngồi đọc sách).","form":[["S/nơi chốn + V + 着 (+ N)","桌子上放着一本书"],["S + V1着 + V2","他笑着说"],["Phủ định: 没(有) + V + 着","门没开着"]],"tips":[],"eg":[["外面下着雨。","wàimiàn xiàzheyǔ.","Bên ngoài đang mưa.",["外面","下着雨","。"]],["墙上挂着一张地图。","qiángshàng guà zhe yīzhāng dìtú.","Trên tường treo một tấm bản đồ.",["墙上","挂","着","一张","地图","。"]],["他喜欢躺着看电视。","tā xǐhuan tǎng zhe kàndiànshì.","Anh ấy thích nằm xem tivi.",["他","喜欢","躺","着","看电视","。"]]],"fix":["他笑了说。","他笑着说。","Vừa làm vừa nói dùng V着.","tā xiào zhe shuō."],"ex":[{"q":"她穿___一件红衣服。","p":"tā chuānzhe yījiàn hóngyīfú.","o":["着","了","过","得"],"a":0,"e":"Trạng thái mặc: 穿着."},{"q":"老师站___上课。","p":"lǎoshī zhàn zhe shàngkè.","o":["着","了","过","得"],"a":0,"e":"Đứng dạy: 站着."},{"q":"门开___，你进来吧。","p":"ménkāi zhe, nǐ jìnlái ba.","o":["着","过","得","的"],"a":0,"e":"Cửa đang mở: 开着."},{"q":"他笑___说：\"没关系。\"","p":"tā xiào zhe shuō: \" méiguānxi. \"","o":["着","了","过","得"],"a":0,"e":"Vừa cười vừa nói: 笑着说."}]},{"lv":2,"id":"h2-haishi","name":"Lựa chọn: 还是 và 或者","zh":"还是 / 或者","use":"还是 dùng trong câu hỏi lựa chọn (A hay B?). 或者 dùng trong câu trần thuật (A hoặc B đều được).","form":[["A + 还是 + B？","你喝茶还是喝咖啡？"],["A + 或者 + B","星期六或者星期天都可以"]],"tips":["Câu có 还是 để hỏi thì không thêm 吗."],"eg":[["你想去北京还是上海？","nǐ xiǎng qù běijīng háishi shànghǎi?","Bạn muốn đi Bắc Kinh hay Thượng Hải?",["你","想","去","北京","还是","上海","？"]],["我们坐地铁或者打车去吧。","wǒmen zuòdìtiě huòzhě dǎchē qù ba.","Chúng ta đi tàu điện ngầm hoặc gọi taxi đi.",["我们","坐地铁","或者","打车","去","吧","。"]],["你是学生还是老师？","nǐ shì xuésheng háishi lǎoshī?","Bạn là học sinh hay giáo viên?",["你","是","学生","还是","老师","？"]]],"fix":["你喝茶或者咖啡？","你喝茶还是咖啡？","Câu hỏi lựa chọn dùng 还是.","nǐ hēchá háishi kāfēi?"],"ex":[{"q":"你今天去___明天去？","p":"nǐ jīntiān qù háishi míngtiān qù?","o":["还是","或者","和","也"],"a":0,"e":"Câu hỏi lựa chọn."},{"q":"周末我在家看书___看电影。","p":"zhōumò wǒ zàijiā kànshū huòzhě kàn diànyǐng.","o":["或者","还是","吗","呢"],"a":0,"e":"Câu trần thuật dùng 或者."},{"q":"这件衣服是红的___白的？","p":"zhèjiàn yīfu shì hóng de háishi bái de?","o":["还是","或者","但是","所以"],"a":0,"e":"Hỏi A hay B."},{"q":"你可以打电话___发短信给我。","p":"nǐ kěyǐ dǎdiànhuà huòzhě fāduǎnxìn gěi wǒ.","o":["或者","还是","和","都"],"a":0,"e":"Hai cách đều được: 或者."}]},{"lv":2,"id":"h2-ji-duo","name":"Số ước lượng và 多","zh":"几 / 多 / 左右","use":"几 + lượng từ trong câu trần thuật = vài. Số + 多 = hơn (三十多岁 = hơn ba mươi tuổi). 多 + adj hỏi mức độ: 多大, 多高, 多长时间.","form":[["几 + lượng từ + N","几本书 (vài quyển sách)"],["Số tròn chục + 多 + lượng từ","二十多个人"],["多 + adj？","你多大？/ 要多长时间？"]],"tips":[],"eg":[["我买了几个苹果。","wǒ mǎi le jǐgè píngguǒ.","Tôi mua vài quả táo.",["我","买","了","几个","苹果","。"]],["教室里有三十多个学生。","jiàoshì lǐ yǒu sānshíduōgè xuésheng.","Trong lớp có hơn ba mươi học sinh.",["教室","里","有","三十多个","学生","。"]],["从这儿到机场要多长时间？","cóng zhèr dào jīchǎng yào duōzhǎngshíjiān?","Từ đây đến sân bay mất bao lâu?",["从","这儿","到","机场","要","多长时间","？"]]],"fix":["他多三十岁。","他三十多岁。","多 đứng sau số.","tā sānshíduōsuì."],"ex":[{"q":"他今年四十___岁。","p":"tā jīnnián sìshíduōsuì.","o":["多","几","些","点"],"a":0,"e":"Hơn bốn mươi: 四十多."},{"q":"你今年___大？","p":"nǐ jīnnián duōdà?","o":["多","几","什么","怎么"],"a":0,"e":"Hỏi tuổi người lớn: 多大."},{"q":"桌子上有___本书。","p":"zhuōzi shàng yǒu jǐběnshū.","o":["几","多","多少个","些个"],"a":0,"e":"Vài quyển: 几本."},{"q":"你每天学习多___时间？","p":"nǐ měitiān xuéxí duōzhǎngshíjiān?","o":["长","少","多","几"],"a":0,"e":"Bao lâu: 多长时间."}]},{"lv":2,"id":"h2-bi","name":"So sánh với 比 và 没有","zh":"比 / 没有…那么","use":"So sánh hơn: A 比 B + tính từ. Muốn nói hơn bao nhiêu thì thêm số lượng sau tính từ; hơn nhiều thì thêm 多了 / 得多. So sánh kém: A 没有 B (那么) + tính từ.","form":[["A + 比 + B + tính từ","我比他高"],["A + 比 + B + tính từ + 一点儿 / 多了 / số lượng","他比我大两岁"],["A + 没有 + B + (那么/这么) + tính từ","今天没有昨天热"]],"tips":["Trong câu 比 không dùng 很, 非常, 太 trước tính từ; muốn nhấn mạnh dùng 更 hoặc 还."],"eg":[["哥哥比我高。","gēge bǐ wǒ gāo.","Anh trai cao hơn tôi.",["哥哥","比","我","高","。"]],["这个比那个便宜多了。","zhège bǐ nàge piányi duō le.","Cái này rẻ hơn cái kia nhiều.",["这个","比","那个","便宜","多","了","。"]],["北京没有上海那么热。","běijīng méiyǒu shànghǎi nàme rè.","Bắc Kinh không nóng bằng Thượng Hải.",["北京","没有","上海","那么","热","。"]]],"fix":["他比我很高。","他比我高多了。","Trong câu 比 không dùng 很.","tā bǐ wǒ gāo duō le."],"ex":[{"q":"今天___昨天冷。","p":"jīntiān bǐ zuótiān lěng.","o":["比","没","跟","对"],"a":0,"e":"A 比 B + tính từ."},{"q":"我比他大___岁。","p":"wǒ bǐ tā dà liǎngsuì.","o":["两","很","太","非常"],"a":0,"e":"Số lượng đặt sau tính từ."},{"q":"地铁比公共汽车___快。","p":"dìtiě bǐ gōnggòngqìchē gèng kuài.","o":["更","很","太","非常"],"a":0,"e":"Nhấn mạnh trong câu 比 dùng 更."},{"q":"我的汉语___你那么好。","p":"wǒ de Hànyǔ méiyǒu nǐ nàme hǎo.","o":["没有","不比","不是","比"],"a":0,"e":"So sánh kém: A 没有 B 那么…."}]},{"lv":2,"id":"h2-jieguo","name":"Bổ ngữ kết quả: 完, 好, 到, 懂, 见, 错","zh":"V + 完/好/到/懂/见/错","use":"Đặt sau động từ để nói kết quả của hành động: 完 xong, 好 xong xuôi/tốt, 到 đạt được/tới, 懂 hiểu, 见 thấy/nghe thấy, 错 sai.","form":[["S + V + bổ ngữ kết quả + (了) + O","我听懂了"],["Phủ định: 没 + V + bổ ngữ kết quả","我没看见他"]],"tips":["看 (nhìn) ≠ 看见 (nhìn thấy); 听 (nghe) ≠ 听懂 (nghe hiểu)."],"eg":[["我做完作业了。","wǒ zuòwánzuòyè le.","Tôi làm xong bài tập rồi.",["我","做完作业","了","。"]],["老师说的话你听懂了吗？","lǎoshī shuō dehuà nǐ tīngdǒng le ma?","Lời thầy nói bạn nghe hiểu chưa?",["老师","说","的话","你","听懂","了","吗","？"]],["我找到我的钥匙了。","wǒ zhǎodào wǒ de yàoshi le.","Tôi tìm thấy chìa khóa rồi.",["我","找到","我","的","钥匙","了","。"]]],"fix":["我不看见他。","我没看见他。","Bổ ngữ kết quả phủ định bằng 没.","wǒ méi kànjiàn tā."],"ex":[{"q":"这本书我已经看___了。","p":"zhè běnshū wǒ yǐjīng kàn wán le.","o":["完","过","着","在"],"a":0,"e":"Làm xong: V + 完."},{"q":"对不起，我写___了一个字。","p":"duìbuqǐ, wǒ xiěcuò le yígè zì.","o":["错","完","见","懂"],"a":0,"e":"Viết sai: 写错."},{"q":"你说得太快，我没听___。","p":"nǐ shuō de tàikuài, wǒ méi tīngdǒng.","o":["懂","完","错","着"],"a":0,"e":"Nghe hiểu: 听懂."},{"q":"我在商店看___了我的老师。","p":"wǒ zài shāngdiàn kànjiàn le wǒ de lǎoshī.","o":["见","懂","完","错"],"a":0,"e":"Nhìn thấy: 看见."}]},{"lv":2,"id":"h2-de","name":"Bổ ngữ trạng thái với 得","zh":"V + 得 + 怎么样","use":"Dùng 得 sau động từ hoặc tính từ để đánh giá mức độ, cách thức của hành động. Nếu có tân ngữ, phải lặp lại động từ.","form":[["S + V + 得 + (很) + tính từ","他跑得很快"],["S + (V) + O + V + 得 + tính từ","她(说)汉语说得很好"],["Phủ định: V + 得 + 不 + tính từ","我写得不好"]],"tips":["Phân biệt: 的 trước danh từ, 地 trước động từ (认真地学习), 得 sau động từ."],"eg":[["你汉字写得真漂亮。","nǐ hànzì xiě de zhēn piàoliang.","Bạn viết chữ Hán đẹp thật.",["你","汉字","写","得","真","漂亮","。"]],["他每天睡得很晚。","tā měitiān shuìdé hěn wǎn.","Ngày nào anh ấy cũng ngủ rất muộn.",["他","每天","睡得","很","晚","。"]],["她唱歌唱得非常好。","tā chàng gēchàng de fēicháng hǎo.","Cô ấy hát rất hay.",["她","唱","歌唱","得","非常","好","。"]]],"fix":["他说汉语得很好。","他说汉语说得很好。","Có tân ngữ thì lặp lại động từ.","tā shuō Hànyǔ shuō de hěn hǎo."],"ex":[{"q":"他跑___很快。","p":"tā pǎo de hěnkuài.","o":["得","的","地","了"],"a":0,"e":"Sau động từ đánh giá: 得."},{"q":"我们要认真___学习。","p":"wǒmen yào rènzhēn de xuéxí.","o":["地","得","的","了"],"a":0,"e":"Trước động từ: 地."},{"q":"她做菜做得___好吃。","p":"tā zuòcài zuò de hěn hǎochī.","o":["很","是","了","的"],"a":0,"e":"V + 得 + 很 + tính từ."},{"q":"你昨天睡得好___？","p":"nǐ zuótiān shuìdé hǎo ma?","o":["吗","呢","吧","的"],"a":0,"e":"Câu hỏi có/không."}]},{"lv":2,"id":"h2-de-de","name":"Ba chữ de: 的, 地, 得","zh":"的 / 地 / 得","use":"的 + danh từ (định ngữ: 我的书). 地 + động từ (trạng ngữ: 高兴地说). Động từ + 得 + đánh giá (bổ ngữ: 说得很好). Cả ba đều đọc là de.","form":[["định ngữ + 的 + N","漂亮的衣服"],["tính từ + 地 + V","认真地学习"],["V + 得 + adj","跑得很快"]],"tips":[],"eg":[["这是我妈妈做的菜。","zhè shì wǒ māma zuò de cài.","Đây là món mẹ tôi nấu.",["这","是","我","妈妈","做","的","菜","。"]],["他高兴地说：\"我考得很好！\"","tā gāoxìng dìshuō: \" wǒ kǎodé hěn hǎo! \"","Anh ấy vui vẻ nói: \"Tôi thi rất tốt!\"",["他","高兴","地说","：","\"","我","考得","很","好","！","\""]],["我们要努力地学习。","wǒmen yào nǔlì de xuéxí.","Chúng ta phải chăm chỉ học tập.",["我们","要","努力","地","学习","。"]]],"fix":["他跑的很快。","他跑得很快。","Sau động từ đánh giá dùng 得.","tā pǎo de hěnkuài."],"ex":[{"q":"这是我新买___手机。","p":"zhè shì wǒ xīn mǎi de shǒujī.","o":["的","地","得","了"],"a":0,"e":"Trước danh từ: 的."},{"q":"孩子们高兴___唱歌。","p":"háizi men gāoxìng de chànggē.","o":["地","的","得","了"],"a":0,"e":"Trước động từ: 地."},{"q":"你汉语说___真好！","p":"nǐ Hànyǔ shuō de zhēn hǎo!","o":["得","的","地","了"],"a":0,"e":"Sau động từ đánh giá: 得."},{"q":"这是一个很有意思___电影。","p":"zhèshì yígè hěn yǒuyìsi de diànyǐng.","o":["的","地","得","了"],"a":0,"e":"Trước danh từ: 的."}]},{"lv":2,"id":"h2-ci","name":"Lượng từ động tác: 次, 遍, 一下","zh":"V + 了 + số + 次","use":"Đếm số lần làm việc gì: V + (了/过) + số + 次. 遍 nhấn mạnh làm trọn từ đầu đến cuối. Nếu tân ngữ là đại từ thì đặt trước 次.","form":[["S + V + 了/过 + số + 次 + N","我去过两次北京"],["S + V + 了 + đại từ + số + 次","我找了他三次"],["S + V + 了 + số + 遍","这本书我看了两遍"]],"tips":[],"eg":[["我去过三次上海。","wǒ qùguò sāncì shànghǎi.","Tôi đã đến Thượng Hải ba lần.",["我","去过","三次","上海","。"]],["这个电影我看了两遍。","zhège diànyǐng wǒ kàn le liǎngbiàn.","Phim này tôi xem hai lần.",["这个","电影","我","看","了","两遍","。"]],["我给他打了几次电话。","wǒ gěi tā dǎ le jǐcì diànhuà.","Tôi gọi điện cho anh ấy mấy lần.",["我","给","他","打","了","几次","电话","。"]]],"fix":["我三次去过北京。","我去过三次北京。","Số lần đặt sau động từ.","wǒ qùguò sāncì běijīng."],"ex":[{"q":"我来过这儿两___。","p":"wǒlái guò zhèr liǎngcì.","o":["次","个","本","条"],"a":0,"e":"Số lần: 次."},{"q":"请把课文读一___。","p":"qǐng bǎ kèwén dú yībiàn.","o":["遍","个","条","本"],"a":0,"e":"Đọc trọn bài: 遍."},{"q":"我找了___三次，他都不在。","p":"wǒ zhǎo le tā sāncì, tā dōu bùzài.","o":["他","他的","次他","他们的"],"a":0,"e":"Đại từ đặt trước 次."},{"q":"这首歌我听了很多___。","p":"zhè shǒugē wǒ tīng le hěnduōbiàn.","o":["遍","个","件","条"],"a":0,"e":"Nghe trọn nhiều lần: 遍."}]},{"lv":2,"id":"h2-jiu-cai","name":"Sớm hay muộn: 就 và 才","zh":"就 / 才","use":"就 nhấn mạnh việc xảy ra sớm, nhanh, dễ (hơn dự kiến). 才 nhấn mạnh việc xảy ra muộn, chậm, khó (hơn dự kiến). Câu có 就 thường có 了; câu có 才 thường không có 了.","form":[["Thời gian + 就 + V + 了","他七点就来了 (bảy giờ đã đến rồi)"],["Thời gian + 才 + V","他十点才来 (mười giờ mới đến)"]],"tips":[],"eg":[["我六点就起床了。","wǒ liùdiǎn jiù qǐchuáng le.","Sáu giờ tôi đã dậy rồi.",["我","六点","就","起床","了","。"]],["他十二点才睡觉。","tā shíèrdiǎn cái shuìjiào.","Mười hai giờ anh ấy mới đi ngủ.",["他","十二点","才","睡觉","。"]],["走路五分钟就到了。","zǒulù wǔfēnzhōng jiù dào le.","Đi bộ năm phút là tới.",["走路","五分钟","就","到","了","。"]]],"fix":["他十点才来了。","他十点才来。","Câu có 才 thường không dùng 了.","tā shídiǎn cái lái."],"ex":[{"q":"电影七点开始，他六点半___来了。","p":"diànyǐng qīdiǎn kāishǐ, tā liùdiǎnbàn jiù lái le.","o":["就","才","再","还"],"a":0,"e":"Đến sớm: 就."},{"q":"上课八点开始，她八点半___来。","p":"shàngkè bādiǎn kāishǐ, tā bādiǎnbàn cái lái.","o":["才","就","再","也"],"a":0,"e":"Đến muộn: 才."},{"q":"我等了一个小时，他___来。","p":"wǒ děng le yígè xiǎoshí, tā cái lái.","o":["才","就","还","再"],"a":0,"e":"Rất lâu mới đến: 才."},{"q":"这个问题很简单，我一看___懂了。","p":"zhège wèntí hěn jiǎndān, wǒ yī kàn jiù dǒng le.","o":["就","才","再","又"],"a":0,"e":"Nhanh, dễ: 就."}]},{"lv":2,"id":"h2-xian-zai","name":"Trình tự hành động: 先…再…然后, 一边…一边","zh":"先 / 再 / 然后 / 一边","use":"先…再…(然后…, 最后…) nói thứ tự các việc. 一边…一边… nói hai việc làm cùng lúc.","form":[["先 + V1，再 + V2，然后 + V3","先洗手，再吃饭"],["一边 + V1，一边 + V2","一边听音乐一边做作业"]],"tips":["再 dùng cho việc chưa xảy ra (sẽ làm lại/làm sau); 又 dùng cho việc đã lặp lại."],"eg":[["我们先吃饭，再去看电影。","wǒmen xiān chīfàn, zài qù kàn diànyǐng.","Chúng ta ăn cơm trước rồi đi xem phim.",["我们","先","吃饭","，","再","去","看","电影","。"]],["他喜欢一边喝咖啡一边看书。","tā xǐhuan yībiān hēkāfēi yībiān kànshū.","Anh ấy thích vừa uống cà phê vừa đọc sách.",["他","喜欢","一边","喝咖啡","一边","看书","。"]],["你先坐一下，我马上来。","nǐ xiān zuò yīxià, wǒ mǎshàng lái.","Bạn ngồi một chút, tôi đến ngay.",["你","先","坐","一下","，","我","马上","来","。"]]],"fix":["他昨天再来了。","他昨天又来了。","Việc đã lặp lại dùng 又.","tā zuótiān yòu lái le."],"ex":[{"q":"你___做作业，再看电视。","p":"nǐ xiān zuòzuòyè, zài kàndiànshì.","o":["先","再","又","就"],"a":0,"e":"Thứ tự: 先…再…."},{"q":"他一边走___打电话。","p":"tā yībiān zǒu yībiān dǎdiànhuà.","o":["一边","再","先","然后"],"a":0,"e":"一边…一边…."},{"q":"今天太晚了，我们明天___说吧。","p":"jīntiān tàiwǎn le, wǒmen míngtiān zàishuō ba.","o":["再","又","还","先"],"a":0,"e":"Việc chưa xảy ra: 再."},{"q":"他上个星期来了，昨天___来了。","p":"tā shànggèxīngqī lái le, zuótiān yòu lái le.","o":["又","再","先","还是"],"a":0,"e":"Việc đã lặp lại: 又."}]},{"lv":2,"id":"h2-yinwei","name":"Nguyên nhân – kết quả: 因为…所以…","zh":"因为 / 所以","use":"因为 nêu nguyên nhân, 所以 nêu kết quả. Có thể dùng cả hai hoặc chỉ một trong hai.","form":[["因为 + nguyên nhân，所以 + kết quả","因为下雨，所以我没去"],["Kết quả + 是因为 + nguyên nhân","我没去，是因为下雨"]],"tips":["Có thể bỏ 因为 hoặc 所以, nhưng không ghép 因为 với 但是. Muốn nhấn mạnh lý do thì đặt nó sau: Kết quả + 是因为 + lý do."],"eg":[["因为我感冒了，所以今天没去上班。","yīnwèi wǒ gǎnmào le, suǒyǐ jīntiān méi qù shàngbān.","Vì tôi bị cảm nên hôm nay không đi làm.",["因为","我","感冒","了","，","所以","今天","没","去","上班","。"]],["他很高兴，因为考试考得很好。","tā hěn gāoxìng, yīnwèi kǎoshì kǎodé hěn hǎo.","Anh ấy rất vui vì thi rất tốt.",["他","很","高兴","，","因为","考试","考得","很","好","。"]],["天气不好，所以飞机晚点了。","tiānqì bùhǎo, suǒyǐ fēijī wǎndiǎn le.","Thời tiết xấu nên máy bay bị trễ.",["天气","不好","，","所以","飞机","晚点","了","。"]]],"fix":["因为下雨了，但是我没去。","因为下雨了，所以我没去。","因为 đi với 所以.","yīnwèi xiàyǔ le, suǒyǐ wǒ méi qù."],"ex":[{"q":"___太累了，所以我想休息。","p":"yīnwèi tàilèi le, suǒyǐ wǒ xiǎng xiūxi.","o":["因为","所以","但是","虽然"],"a":0,"e":"Nguyên nhân dùng 因为."},{"q":"因为路上堵车，___我迟到了。","p":"yīnwèi lùshang dǔchē, suǒyǐ wǒ chídào le.","o":["所以","因为","但是","还是"],"a":0,"e":"Kết quả dùng 所以."},{"q":"我喜欢他，___他很热情。","p":"wǒ xǐhuan tā, yīnwèi tā hěn rèqíng.","o":["因为","所以","如果","或者"],"a":0,"e":"Nguyên nhân đặt sau."},{"q":"他没来，是___他生病了。","p":"tā méilái, shìyīnwèi tā shēngbìng le.","o":["因为","所以","但是","还是"],"a":0,"e":"Kết quả + 是因为 + nguyên nhân."}]},{"lv":3,"id":"h3-ba","name":"Câu chữ 把","zh":"S + 把 + O + V + thành phần khác","use":"Câu 把 nhấn mạnh việc chủ ngữ tác động lên một vật xác định và làm nó thay đổi (vị trí, trạng thái). Sau động từ phải có thành phần khác (了, bổ ngữ, nơi chốn…).","form":[["S + 把 + O + V + 了/bổ ngữ","我把作业做完了"],["S + 把 + O + V + 在/到/给 + …","请把书放在桌子上"],["Phủ định: S + 没/不 + 把 + O + V…","我没把门关上"]],"tips":["不/没/想/要/能 đặt trước 把, không đặt trước động từ.","Tân ngữ của 把 phải là vật cụ thể, xác định (这本书, 我的手机)."],"eg":[["请把窗户打开。","qǐng bǎ chuānghu dǎkāi.","Làm ơn mở cửa sổ ra.",["请","把","窗户","打开","。"]],["我把钱包忘在出租车上了。","wǒ bǎ qiánbāo wàng zài chūzūchē shàng le.","Tôi để quên ví trên taxi rồi.",["我","把","钱包","忘","在","出租车","上","了","。"]],["他把这件事告诉了妈妈。","tā bǎ zhèjiàn shì gàosu le māma.","Anh ấy đã kể chuyện này với mẹ.",["他","把","这件","事","告诉","了","妈妈","。"]]],"fix":["我把作业做。","我把作业做完了。","Sau động từ trong câu 把 phải có thành phần khác.","wǒ bǎ zuòyè zuò wán le."],"ex":[{"q":"请你___护照给我看一下。","p":"qǐng nǐ bǎ hùzhào gěi wǒ kàn yīxià.","o":["把","被","让","给"],"a":0,"e":"Câu 把: 把 + O + V + 给."},{"q":"我没___手机带来。","p":"wǒ méi bǎ shǒujī dàilái.","o":["把","被","叫","从"],"a":0,"e":"Phủ định đặt trước 把."},{"q":"他把杯子放___桌子上了。","p":"tā bǎ bēizi fàngzài zhuōzi shàng le.","o":["在","到了","着","过"],"a":0,"e":"V + 在 + nơi chốn."},{"q":"你把这些衣服洗___吧。","p":"nǐ bǎ zhèxiē yīfu xǐ gānjìng ba.","o":["干净","干干净","很干净","得干净"],"a":0,"e":"V + bổ ngữ kết quả."}]},{"lv":3,"id":"h3-bei","name":"Câu bị động với 被","zh":"S + 被 + (người) + V + …","use":"被 dùng khi chủ ngữ chịu tác động, thường là việc không mong muốn. Người gây ra hành động có thể lược bỏ. Sau động từ cũng phải có thành phần khác.","form":[["S + 被 + người + V + 了/bổ ngữ","我的自行车被他骑走了"],["S + 被 + V + 了","我的手机被偷了"],["S + 叫/让 + người + V + …","văn nói, bắt buộc có người thực hiện"]],"tips":["没/不/已经 đặt trước 被."],"eg":[["我的蛋糕被弟弟吃了。","wǒ de dàngāo bèi dìdi chī le.","Bánh của tôi bị em trai ăn mất.",["我","的","蛋糕","被","弟弟","吃","了","。"]],["他被老师批评了。","tā bèi lǎoshī pīpíng le.","Anh ấy bị thầy phê bình.",["他","被","老师","批评","了","。"]],["那本书已经被借走了。","nàběnshū yǐjīng bèi jièzǒu le.","Quyển sách đó đã bị mượn đi rồi.",["那本书","已经","被","借走","了","。"]]],"fix":["我的钱包被偷。","我的钱包被偷了。","Sau động từ cần 了 hoặc bổ ngữ.","wǒ de qiánbāo bèi tōu le."],"ex":[{"q":"我的雨伞___别人拿走了。","p":"wǒ de yǔsǎn bèi biéren názǒu le.","o":["被","把","给了","对"],"a":0,"e":"Bị động dùng 被."},{"q":"窗户被风吹___了。","p":"chuānghu bèi fēngchuī kāi le.","o":["开","开开","着","过"],"a":0,"e":"V + bổ ngữ kết quả."},{"q":"他的电脑没___弄坏。","p":"tā de diànnǎo méi bèi nònghuài.","o":["被","把","对","给"],"a":0,"e":"没 đặt trước 被."},{"q":"这件事已经___大家知道了。","p":"zhèjiàn shì yǐjīng bèi dàjiā zhīdào le.","o":["被","把","向","对"],"a":0,"e":"Bị động: 被 + 大家 + 知道."}]},{"lv":3,"id":"h3-quxiang","name":"Bổ ngữ xu hướng: 来, 去 và 上/下/进/出/回/过/起","zh":"V + 来/去; V + 上/下/进/出 + 来/去","use":"来 hướng về phía người nói, 去 hướng ra xa người nói. Kết hợp 上下进出回过起 + 来/去 để chỉ hướng cụ thể. Một số còn nghĩa mở rộng: 想起来 (nhớ ra), 看起来 (trông có vẻ), 坚持下去 (tiếp tục).","form":[["V + 来/去","你过来 / 他回去了"],["V + 上/下/进/出/回/过/起 + 来/去","他走进来了"],["Tân ngữ nơi chốn đặt trước 来/去","他走进教室来了"]],"tips":["看起来 = trông có vẻ; 想起来 = nhớ ra; 听起来 = nghe có vẻ."],"eg":[["老师走进来了。","lǎoshī zǒujìn lái le.","Thầy giáo đi vào rồi.",["老师","走进","来","了","。"]],["你什么时候回去？","nǐ shénme shíhou huíqu?","Khi nào bạn về?",["你","什么","时候","回去","？"]],["这个菜看起来很好吃。","zhège cài kànqǐlái hěn hǎochī.","Món này trông có vẻ ngon.",["这个","菜","看起来","很","好吃","。"]]],"fix":["他走进来教室了。","他走进教室来了。","Nơi chốn đặt trước 来.","tā zǒujìn jiàoshì lái le."],"ex":[{"q":"我在楼上，你上___吧。","p":"wǒ zài lóushàng, nǐ shànglái ba.","o":["来","去","过","着"],"a":0,"e":"Hướng về phía người nói: 来."},{"q":"我想___了，他叫小王。","p":"wǒ xiǎng qǐlai le, tā jiào xiǎowáng.","o":["起来","下去","出去","过来"],"a":0,"e":"Nhớ ra: 想起来."},{"q":"这件事听___很有意思。","p":"zhèjiàn shì tīng qǐlai hěn yǒuyìsi.","o":["起来","下来","出来","过来"],"a":0,"e":"Nghe có vẻ: 听起来."},{"q":"虽然很难，但我们要坚持___。","p":"suīrán hěnnán, dàn wǒmen yào jiānchíxiàqù.","o":["下去","起来","上来","过去"],"a":0,"e":"Tiếp tục: 坚持下去."}]},{"lv":3,"id":"h3-keneng","name":"Bổ ngữ khả năng: V + 得/不 + bổ ngữ","zh":"看得懂 / 听不清楚","use":"Chèn 得 hoặc 不 giữa động từ và bổ ngữ kết quả/xu hướng để nói có thể hay không thể đạt kết quả.","form":[["V + 得 + bổ ngữ","看得懂 (đọc hiểu được)"],["V + 不 + bổ ngữ","吃不完 (ăn không hết)"],["Câu hỏi: V得C + V不C？","你听得懂听不懂？"]],"tips":["Không thể làm do điều kiện khách quan thường dùng bổ ngữ khả năng, không dùng 不能: 我听不懂, không nói 我不能听懂."],"eg":[["黑板上的字你看得清楚吗？","hēibǎn shàng de zì nǐ kàn de qīngchu ma?","Chữ trên bảng bạn nhìn rõ không?",["黑板","上","的","字","你","看","得","清楚","吗","？"]],["菜太多了，我吃不完。","càitàiduō le, wǒ chībùwán.","Nhiều món quá, tôi ăn không hết.",["菜太多","了","，","我","吃不完","。"]],["他说得太快，我听不懂。","tā shuō de tàikuài, wǒ tīngbùdǒng.","Anh ấy nói nhanh quá, tôi nghe không hiểu.",["他","说","得","太快","，","我","听不懂","。"]]],"fix":["我不能听懂。","我听不懂。","Dùng bổ ngữ khả năng.","wǒ tīngbùdǒng."],"ex":[{"q":"这么多作业，我今天做___完。","p":"zhème duō zuòyè, wǒ jīntiān zuò bù wán.","o":["不","没","得不","不得"],"a":0,"e":"Không thể làm xong: 做不完."},{"q":"门太小，桌子搬不___去。","p":"mén tàixiǎo, zhuōzi bān bù jìnqù.","o":["进","进来","出来","上来"],"a":0,"e":"搬不进去."},{"q":"你一个人拿___了吗？","p":"nǐ yígè rénnádédòng le ma?","o":["得动","不动得","得不","动得"],"a":0,"e":"Hỏi có mang nổi không: 拿得动."},{"q":"这本书太难，我看___。","p":"zhè běnshū tàinán, wǒ kànbùdǒng.","o":["不懂","没懂","不能懂","得不懂"],"a":0,"e":"Đọc không hiểu: 看不懂."}]},{"lv":3,"id":"h3-yue","name":"越来越 và 越…越…","zh":"越来越 / 越…越…","use":"越来越 + tính từ/động từ tâm lý = ngày càng… 越 A 越 B = càng A càng B.","form":[["S + 越来越 + tính từ","天气越来越冷"],["S + 越 + V/adj + 越 + adj","你越说我越不明白"]],"tips":["Không dùng 很, 非常 sau 越来越: không nói 越来越很好."],"eg":[["他的汉语越来越好了。","tā de Hànyǔ yuèláiyuè hǎo le.","Tiếng Trung của anh ấy ngày càng tốt.",["他","的","汉语","越来越","好","了","。"]],["雨越下越大。","yǔyuè xià yuè dà.","Mưa càng lúc càng to.",["雨越","下","越","大","。"]],["这本书我越看越喜欢。","zhè běnshū wǒ yuè kàn yuè xǐhuan.","Quyển sách này tôi càng đọc càng thích.",["这","本书","我","越","看","越","喜欢","。"]]],"fix":["天气越来越很热。","天气越来越热。","Sau 越来越 không dùng 很.","tiānqì yuèláiyuè rè."],"ex":[{"q":"来学汉语的人___多了。","p":"láixué Hànyǔ de rén yuèláiyuè duō le.","o":["越来越","越越","更来更","越更"],"a":0,"e":"Ngày càng: 越来越."},{"q":"他越想越___。","p":"tā yuè xiǎng yuè shēngqì.","o":["生气","很生气","非常生气","太生气"],"a":0,"e":"越 A 越 B, B không thêm 很."},{"q":"风越刮___大。","p":"fēngyuè guā yuè dà.","o":["越","更","还","最"],"a":0,"e":"越…越…."},{"q":"我觉得汉语越学越有意思___。","p":"wǒ juéde Hànyǔ yuèxuéyuè yǒuyìsi le.","o":["了","的","过","着"],"a":0,"e":"Thay đổi: thêm 了."}]},{"lv":3,"id":"h3-suiran","name":"Nhượng bộ và tăng tiến: 虽然…但是, 不但…而且","zh":"虽然 / 但是 / 不但 / 而且","use":"虽然…但是/可是… = tuy… nhưng… 不但…而且/还… = không những… mà còn…","form":[["虽然 + A，但是 + B","虽然很累，但是很开心"],["不但 + A，而且 + B","他不但会说汉语，而且说得很好"]],"tips":["Cùng chủ ngữ thì 不但 đặt sau chủ ngữ; khác chủ ngữ thì 不但 đặt trước chủ ngữ thứ nhất."],"eg":[["虽然下雨了，但是我们还是去了公园。","suīrán xiàyǔ le, dànshì wǒmen háishi qù le gōngyuán.","Tuy trời mưa nhưng chúng tôi vẫn đi công viên.",["虽然","下雨","了","，","但是","我们","还是","去","了","公园","。"]],["这家饭店的菜不但便宜，而且好吃。","zhèjiā fàndiàn de cài bùdàn piányi, érqiě hǎochī.","Món ở nhà hàng này không những rẻ mà còn ngon.",["这家","饭店","的","菜","不但","便宜","，","而且","好吃","。"]],["她虽然很忙，可是每天都锻炼身体。","tā suīrán hěn máng, kěshì měitiān dōu duànliànshēntǐ.","Tuy rất bận nhưng ngày nào cô ấy cũng tập thể dục.",["她","虽然","很","忙","，","可是","每天","都","锻炼身体","。"]]],"fix":["虽然他很累，所以还在工作。","虽然他很累，但是还在工作。","虽然 đi với 但是/可是.","suīrán tā hěn lèi, dànshì hái zài gōngzuò."],"ex":[{"q":"虽然汉语很难，___我很喜欢学。","p":"suīrán Hànyǔ hěnnán, dànshì wǒ hěn xǐhuan xué.","o":["但是","所以","而且","因为"],"a":0,"e":"虽然…但是."},{"q":"他不但会唱歌，___会跳舞。","p":"tā bùdàn huì chànggē, érqiě huì tiàowǔ.","o":["而且","但是","所以","或者"],"a":0,"e":"不但…而且."},{"q":"___天气不好，但是飞机准时起飞了。","p":"suīrán tiānqì bùhǎo, dànshì fēijī zhǔnshí qǐfēi le.","o":["虽然","因为","不但","如果"],"a":0,"e":"Nhượng bộ: 虽然."},{"q":"不但我喜欢她，___我的家人也喜欢她。","p":"bùdàn wǒ xǐhuan tā, érqiě wǒ de jiārén yě xǐhuan tā.","o":["而且","但是","所以","还是"],"a":0,"e":"Khác chủ ngữ: 不但 + S1, 而且 + S2."}]},{"lv":3,"id":"h3-ruguo","name":"Điều kiện: 如果…就, 只要…就, 只有…才","zh":"如果 / 只要 / 只有 / 就 / 才","use":"如果…就… = nếu… thì… 只要…就… = chỉ cần… là… (điều kiện đủ). 只有…才… = chỉ khi… mới… (điều kiện duy nhất).","form":[["如果 + điều kiện，(S) + 就 + kết quả","如果明天下雨，我们就不去了"],["只要 + điều kiện，就 + kết quả","只要努力，就能成功"],["只有 + điều kiện，才 + kết quả","只有多练习，才能说得好"]],"tips":["就, 才 là phó từ: đặt sau chủ ngữ, trước động từ."],"eg":[["如果你有时间，就来我家玩儿吧。","rúguǒ nǐ yǒu shíjiān, jiù lái wǒjiā wánér ba.","Nếu bạn có thời gian thì đến nhà tôi chơi nhé.",["如果","你","有","时间","，","就","来","我家","玩儿","吧","。"]],["只要你喜欢，就买吧。","zhǐyào nǐ xǐhuan, jiù mǎi ba.","Chỉ cần bạn thích là mua thôi.",["只要","你","喜欢","，","就","买","吧","。"]],["只有通过考试，才能拿到证书。","zhǐyǒu tōngguò kǎoshì, cáinéng nádào zhèngshū.","Chỉ khi thi đỗ mới nhận được chứng chỉ.",["只有","通过","考试","，","才能","拿到","证书","。"]]],"fix":["只有多练习，就能说好。","只有多练习，才能说好。","只有 đi với 才.","zhǐyǒu duō liànxí, cáinéng shuōhǎo."],"ex":[{"q":"只要你认真学，___一定能学好。","p":"zhǐyào nǐ rènzhēn xué, jiù yīdìng néng xuéhǎo.","o":["就","才","都","也"],"a":0,"e":"只要…就."},{"q":"只有你去请他，他___会来。","p":"zhǐyǒu nǐ qù qǐng tā, tā cái huì lái.","o":["才","就","都","还"],"a":0,"e":"只有…才."},{"q":"___明天天气好，我们就去爬山。","p":"rúguǒ míngtiān tiānqì hǎo, wǒmen jiù qù páshān.","o":["如果","虽然","因为","不但"],"a":0,"e":"Giả định: 如果."},{"q":"你如果不舒服，___早点儿休息吧。","p":"nǐ rúguǒ bù shūfu, jiù zǎodiǎnér xiūxi ba.","o":["就","才","也","还"],"a":0,"e":"如果…就."}]},{"lv":3,"id":"h3-lian","name":"连…都/也 và 除了…以外","zh":"连…都 / 除了…以外…都/还","use":"连…都/也… = ngay cả… cũng… (nhấn mạnh). 除了…以外，都… = ngoài… ra thì đều… (loại trừ); 除了…以外，还/也… = ngoài… ra còn… (bổ sung).","form":[["连 + đối tượng + 都/也 + V","他连饭都没吃"],["除了 A 以外，B 都 + V","除了他以外，我们都去了"],["除了 A 以外，(S) 还 + V + B","除了汉语，我还学日语"]],"tips":[],"eg":[["他忙得连吃饭的时间都没有。","tā máng de lián chīfàn de shíjiān dōu méiyǒu.","Anh ấy bận đến mức ngay cả thời gian ăn cơm cũng không có.",["他","忙","得","连","吃饭","的","时间","都","没有","。"]],["这个问题连老师都不知道。","zhège wèntí lián lǎoshī dōu bù zhīdào.","Câu hỏi này ngay cả thầy cũng không biết.",["这个","问题","连","老师","都","不","知道","。"]],["除了周末以外，我每天都上班。","chúle zhōumò yǐwài, wǒ měitiān dōu shàngbān.","Ngoài cuối tuần ra, ngày nào tôi cũng đi làm.",["除了","周末","以外","，","我","每天","都","上班","。"]]],"fix":["连小孩子知道这件事。","连小孩子都知道这件事。","连 phải đi với 都/也.","lián xiǎoháizi dōu zhīdào zhèjiàn shì."],"ex":[{"q":"这么简单的题，___我都会做。","p":"zhème jiǎndān de tí, lián wǒ dūhuì zuò.","o":["连","除了","因为","比"],"a":0,"e":"Nhấn mạnh: 连…都."},{"q":"除了跑步以外，我___喜欢游泳。","p":"chúle pǎobù yǐwài, wǒ hái xǐhuan yóuyǒng.","o":["还","都","才","就"],"a":0,"e":"Bổ sung: 除了…还."},{"q":"除了小王，大家___来了。","p":"chúle xiǎowáng, dàjiā dōu lái le.","o":["都","还","也是","就"],"a":0,"e":"Loại trừ: 除了…都."},{"q":"他连一句汉语___不会说。","p":"tā lián yījù Hànyǔ yě búhuì shuō.","o":["也","还","就","才"],"a":0,"e":"连…也."}]},{"lv":4,"id":"h4-shide","name":"Cấu trúc 是…的 nhấn mạnh","zh":"是 + thời gian/nơi chốn/cách thức + V + 的","use":"Dùng khi việc đã xảy ra, cần nhấn mạnh thời gian, nơi chốn, cách thức, người làm hoặc mục đích của nó.","form":[["S + 是 + (thời gian/nơi/cách) + V + 的","我是昨天到的"],["Tân ngữ có thể đặt sau 的","我是在北京学的汉语"],["Phủ định: S + 不是 + … + V + 的","我不是坐飞机来的"]],"tips":["Không dùng 了 trong cấu trúc 是…的."],"eg":[["你是什么时候来中国的？","nǐ shì shénme shíhou lái Zhōngguó de?","Bạn sang Trung Quốc lúc nào?",["你","是","什么","时候","来","中国","的","？"]],["我是坐高铁去的上海。","wǒ shì zuò gāotiě qù de shànghǎi.","Tôi đi Thượng Hải bằng tàu cao tốc.",["我","是","坐","高铁","去","的","上海","。"]],["这件衣服是妈妈给我买的。","zhèjiàn yīfu shì māma gěi wǒ mǎi de.","Cái áo này là mẹ mua cho tôi.",["这件","衣服","是","妈妈","给","我","买","的","。"]]],"fix":["我是昨天来了的。","我是昨天来的。","是…的 không dùng 了.","wǒ shì zuótiān lái de."],"ex":[{"q":"你是怎么来___？","p":"nǐ shì zěnme lái de?","o":["的","了","过","着"],"a":0,"e":"Nhấn mạnh cách thức: 是…的."},{"q":"我们___在大学认识的。","p":"wǒmen shì zài dàxué rènshi de.","o":["是","就","在","都"],"a":0,"e":"是 + nơi chốn + V + 的."},{"q":"这个菜不是我做___，是我朋友做的。","p":"zhège cài búshì wǒ zuò de, shì wǒ péngyou zuò de.","o":["的","了","过","得"],"a":0,"e":"Phủ định: 不是…的."},{"q":"他是去年___中国的。","p":"tā shì qùnián lái Zhōngguó de.","o":["来","来了","来过","来着"],"a":0,"e":"是 + thời gian + V + 的."}]},{"lv":4,"id":"h4-shiliang","name":"Bổ ngữ thời lượng và động lượng","zh":"V + 了 + 一个小时 / 三次","use":"Bổ ngữ thời lượng cho biết hành động kéo dài bao lâu; bổ ngữ động lượng cho biết làm mấy lần (次, 遍, 趟, 下).","form":[["S + V + 了 + thời lượng + (的) + O","我学了两年(的)汉语"],["S + V + O + V + 了 + thời lượng","我学汉语学了两年"],["S + V + 了 + số + 次/遍/趟 + O","我去过三次北京"]],"tips":["Thời gian kể từ khi việc xảy ra: V + O + thời lượng: 他来中国三年了 (đã sang TQ được ba năm).","遍 nhấn mạnh trọn từ đầu đến cuối; 趟 một chuyến đi về."],"eg":[["我每天跑步跑半个小时。","wǒ měitiān pǎobù pǎo bàngè xiǎoshí.","Mỗi ngày tôi chạy bộ nửa tiếng.",["我","每天","跑步","跑","半个","小时","。"]],["这个电影我看了两遍。","zhège diànyǐng wǒ kàn le liǎngbiàn.","Phim này tôi xem hai lần.",["这个","电影","我","看","了","两遍","。"]],["他已经毕业五年了。","tā yǐjīng bìyè wǔnián le.","Anh ấy đã tốt nghiệp được năm năm rồi.",["他","已经","毕业","五年","了","。"]]],"fix":["我两个小时等了你。","我等了你两个小时。","Thời lượng đặt sau động từ.","wǒ děng le nǐ liǎnggè xiǎoshí."],"ex":[{"q":"我在北京住___三年。","p":"wǒ zài běijīng zhù le sānnián.","o":["了","过了","着","的"],"a":0,"e":"V + 了 + thời lượng."},{"q":"请再说一___。","p":"qǐng zàishuō yībiàn.","o":["遍","个","下儿","趟"],"a":0,"e":"Nói lại một lần trọn vẹn: 一遍."},{"q":"我昨天去了一___银行。","p":"wǒ zuótiān qù le yītàng yínháng.","o":["趟","遍","个","张"],"a":0,"e":"Một chuyến đi về: 一趟."},{"q":"他学汉语学___两年了。","p":"tāxué Hànyǔ xuéle liǎngnián le.","o":["了","过","着","的"],"a":0,"e":"V + O + V + 了 + thời lượng."}]},{"lv":4,"id":"h4-wulun","name":"Điều kiện tuyệt đối: 无论/不管…都…","zh":"无论 / 不管 / 都","use":"无论 (trang trọng) / 不管 (văn nói) … 都/也 … = dù… thế nào thì cũng… Sau 无论/不管 phải là cụm có lựa chọn: đại từ nghi vấn, A 还是 B, hoặc A不A.","form":[["无论 + 谁/什么/怎么/多… ，都 + kết quả","无论多忙，他都坚持锻炼"],["不管 + A 还是 B，都 + kết quả","不管下雨还是刮风，他都来"]],"tips":["Không dùng 无论 với câu chỉ một điều kiện cố định: không nói 无论很忙."],"eg":[["无论遇到什么困难，我们都不会放弃。","wúlùn yùdào shénme kùnnan, wǒmen dōu búhuì fàngqì.","Dù gặp khó khăn gì chúng tôi cũng không bỏ cuộc.",["无论","遇到","什么","困难","，","我们","都","不会","放弃","。"]],["不管你去不去，我都要去。","bùguǎn nǐ qùbùqù, wǒ dōu yào qù.","Dù bạn có đi hay không, tôi vẫn đi.",["不管","你","去不去","，","我","都","要","去","。"]],["无论谁来，都要先登记。","wúlùnshuí lái, dōu yào xiān dēngjì.","Dù ai đến cũng phải đăng ký trước.",["无论谁","来","，","都","要","先","登记","。"]]],"fix":["无论天气很冷，他都去跑步。","无论天气多冷，他都去跑步。","Sau 无论 cần từ nghi vấn hoặc lựa chọn.","wúlùn tiānqì duōlěng, tā dōu qù pǎobù."],"ex":[{"q":"无论做什么事，他___很认真。","p":"wúlùn zuò shénme shì, tā dōu hěn rènzhēn.","o":["都","就","才","还"],"a":0,"e":"无论…都."},{"q":"不管你同意___，我都要试一试。","p":"bùguǎn nǐ tóngyì bù tóngyì, wǒ dōu yào shìyīshì.","o":["不同意","吗","还","了"],"a":0,"e":"不管 + A 不 A."},{"q":"___多晚，他都会给妈妈打电话。","p":"wúlùn duōwǎn, tā dūhuì gěi māma dǎdiànhuà.","o":["无论","虽然","因为","只要"],"a":0,"e":"无论 + 多…."},{"q":"不管是大人___小孩，都喜欢这部电影。","p":"bùguǎn shì dàren háishi xiǎohái, dōu xǐhuan zhèbù diànyǐng.","o":["还是","或者","和","也"],"a":0,"e":"不管 A 还是 B."}]},{"lv":4,"id":"h4-jishi","name":"Giả định nhượng bộ: 即使…也…, 哪怕…也…","zh":"即使 / 哪怕 / 也","use":"即使/哪怕… 也… = cho dù (giả sử)… cũng… Vế đầu thường là điều chưa xảy ra hoặc giả định.","form":[["即使 + giả định，(S) + 也 + kết quả","即使下雨，比赛也会进行"],["哪怕 + giả định，也 + kết quả","哪怕只有一点儿希望，也要试试"]],"tips":["So sánh: 虽然 nói sự thật đã có; 即使 nói giả định."],"eg":[["即使工作再忙，你也要注意身体。","jíshǐ gōngzuò zài máng, nǐ yě yào zhùyì shēntǐ.","Cho dù công việc bận đến đâu, bạn cũng phải chú ý sức khỏe.",["即使","工作","再","忙","，","你","也","要","注意","身体","。"]],["哪怕失败了，我也不后悔。","nǎpà shībài le, wǒ yě bù hòuhuǐ.","Cho dù thất bại, tôi cũng không hối hận.",["哪怕","失败","了","，","我","也","不","后悔","。"]],["即使明天不上班，我也要早起。","jíshǐ míngtiān bù shàngbān, wǒ yě yào zǎoqǐ.","Cho dù mai không đi làm, tôi cũng dậy sớm.",["即使","明天","不","上班","，","我","也","要","早起","。"]]],"fix":["即使下雨，比赛就继续。","即使下雨，比赛也继续。","即使 đi với 也.","jíshǐ xiàyǔ, bǐsài yě jìxù."],"ex":[{"q":"即使你不说，我___知道。","p":"jíshǐ nǐ bù shuō, wǒ yě zhīdào.","o":["也","就","才","都是"],"a":0,"e":"即使…也."},{"q":"___只有十分钟，我们也要练习。","p":"nǎpà zhǐyǒu shífēnzhōng, wǒmen yě yào liànxí.","o":["哪怕","虽然","因为","只要"],"a":0,"e":"Giả định: 哪怕."},{"q":"即使很贵，他___要买。","p":"jíshǐ hěn guì, tā yě yào mǎi.","o":["也","就","才","所以"],"a":0,"e":"即使…也."},{"q":"___明天下大雨，运动会也照常举行。","p":"jíshǐ míngtiān xià dàyǔ, yùndònghuì yě zhàocháng jǔxíng.","o":["即使","虽然","因为","如果就"],"a":0,"e":"Giả định chưa xảy ra: 即使."}]},{"lv":4,"id":"h4-jiran","name":"既然…就…","zh":"既然 / 就","use":"既然 nêu một sự thật đã rõ, vế sau đưa ra kết luận hoặc lời khuyên dựa trên sự thật đó (= đã… thì…).","form":[["既然 + sự thật，(S) + 就 + kết luận/đề nghị","既然你不舒服，就回家休息吧"]],"tips":["Khác 如果 (giả định), 既然 nói điều cả hai bên đều đã biết là thật."],"eg":[["既然你已经决定了，就别再犹豫了。","jìrán nǐ yǐjīng juédìng le, jiùbié zài yóuyù le.","Bạn đã quyết định rồi thì đừng do dự nữa.",["既然","你","已经","决定","了","，","就别","再","犹豫","了","。"]],["既然来了，就多住几天吧。","jìrán lái le, jiù duō zhù jǐtiān ba.","Đã đến rồi thì ở thêm vài ngày nhé.",["既然","来","了","，","就","多","住","几天","吧","。"]],["既然大家都同意，我们就这么办。","jìrán dàjiā dōu tóngyì, wǒmen jiù zhème bàn.","Mọi người đã đồng ý thì chúng ta làm như vậy.",["既然","大家","都","同意","，","我们","就","这么","办","。"]]],"fix":["既然你喜欢，才买吧。","既然你喜欢，就买吧。","既然 đi với 就.","jìrán nǐ xǐhuan, jiù mǎi ba."],"ex":[{"q":"既然你知道错了，___改吧。","p":"jìrán nǐ zhīdào cuò le, jiù gǎi ba.","o":["就","才","也","都"],"a":0,"e":"既然…就."},{"q":"___时间不多了，我们快点儿走吧。","p":"jìrán shíjiān bùduō le, wǒmen kuàidiǎnér zǒu ba.","o":["既然","虽然","即使","无论"],"a":0,"e":"Sự thật đã biết: 既然."},{"q":"既然下雨了，我们___别出去了。","p":"jìrán xiàyǔ le, wǒmen jiù biéchūqù le.","o":["就","才","还","都"],"a":0,"e":"既然…就."},{"q":"既然他不想去，你___别勉强他了。","p":"jìrán tā bùxiǎng qù, nǐ jiù bié miǎnqiǎng tā le.","o":["就","才","也是","还是"],"a":0,"e":"Lời khuyên: 就."}]},{"lv":4,"id":"h4-fanwen","name":"Câu hỏi tu từ: 难道…吗, 不是…吗","zh":"难道 / 不是…吗 / 怎么能","use":"Câu hỏi tu từ không cần trả lời, dùng để khẳng định mạnh hơn: câu dạng phủ định mang nghĩa khẳng định và ngược lại.","form":[["难道 + câu + 吗？","难道你不知道吗？(= chắc chắn bạn biết)"],["不是 + … + 吗？","你不是说要来吗？(= bạn đã nói sẽ đến mà)"],["怎么能 / 哪儿 + V…？","我怎么能不去呢？(= tôi nhất định phải đi)"]],"tips":[],"eg":[["难道你忘了今天是我的生日吗？","nándào nǐ wàng le jīntiān shì wǒ de shēngrì ma?","Lẽ nào bạn quên hôm nay là sinh nhật tôi?",["难道","你","忘","了","今天","是","我","的","生日","吗","？"]],["你不是已经吃过饭了吗？","nǐ búshì yǐjīng chīguòfàn le ma?","Chẳng phải bạn đã ăn cơm rồi sao?",["你","不是","已经","吃过饭","了","吗","？"]],["这么重要的事，我怎么能忘呢？","zhème zhòngyào de shì, wǒ zěnme néng wàng ne?","Việc quan trọng thế này, sao tôi quên được?",["这么","重要","的","事","，","我","怎么","能","忘","呢","？"]]],"fix":["难道你不知道呢？","难道你不知道吗？","难道 thường đi với 吗.","nándào nǐ bù zhīdào ma?"],"ex":[{"q":"___你连这个字都不认识吗？","p":"nándào nǐ lián zhège zì dōu bù rènshi ma?","o":["难道","虽然","即使","既然"],"a":0,"e":"Câu hỏi tu từ: 难道…吗."},{"q":"你不是喜欢吃辣的___？","p":"nǐ búshì xǐhuan chī là de ma?","o":["吗","呢","吧","了"],"a":0,"e":"不是…吗."},{"q":"这么好的机会，我___能放弃呢？","p":"zhème hǎo de jīhuì, wǒ zěnme néng fàngqì ne?","o":["怎么","什么","为了","难道是"],"a":0,"e":"怎么能…呢."},{"q":"他___是你的老同学吗？你怎么不认识？","p":"tā búshì nǐ de lǎotóngxué ma? nǐ zěnme bù rènshi?","o":["不","没","别","难"],"a":0,"e":"不是…吗."}]},{"lv":4,"id":"h4-youyu","name":"Nguyên nhân – kết quả trang trọng: 由于, 因此, 于是","zh":"由于 / 因此 / 于是 / 结果","use":"由于 (do, vì) trang trọng hơn 因为, hay đi với 因此/所以. 因此 = vì vậy. 于是 = thế là (việc sau xảy ra tiếp theo việc trước). 结果 = kết quả là (thường không như mong muốn).","form":[["由于 + nguyên nhân，因此/所以 + kết quả","由于天气原因，航班取消了"],["A，于是 + B","他听说那里很美，于是决定去看看"]],"tips":["因为 có thể đi với 所以, nhưng 因为 ít đi với 因此; 由于 đi được với cả 因此 và 所以."],"eg":[["由于准备充分，因此比赛很顺利。","yóuyú zhǔnbèichōngfèn, yīncǐ bǐsài hěn shùnlì.","Do chuẩn bị kỹ nên cuộc thi diễn ra suôn sẻ.",["由于","准备充分","，","因此","比赛","很","顺利","。"]],["大家都没意见，于是会议就结束了。","dàjiā dōu méi yìjiàn, yúshì huìyì jiù jiéshù le.","Mọi người đều không có ý kiến, thế là cuộc họp kết thúc.",["大家","都","没","意见","，","于是","会议","就","结束","了","。"]],["他没带伞，结果被雨淋湿了。","tā méidài sǎn, jiéguǒ bèi yǔlín shī le.","Anh ấy không mang ô, kết quả là bị mưa ướt.",["他","没带","伞","，","结果","被","雨淋","湿","了","。"]]],"fix":["由于下雪，于是路很滑。","由于下雪，因此路很滑。","Quan hệ nhân quả dùng 因此.","yóuyú xiàxuě, yīncǐ lù hěn huá."],"ex":[{"q":"___交通堵塞，很多人迟到了。","p":"yóuyú jiāotōngdǔsè, hěnduō rén chídào le.","o":["由于","于是","因此","结果"],"a":0,"e":"Nguyên nhân trang trọng: 由于."},{"q":"他工作很努力，___得到了提升。","p":"tā gōngzuò hěn nǔlì, yīncǐ dédào le tíshēng.","o":["因此","由于","即使","虽然"],"a":0,"e":"Vì vậy: 因此."},{"q":"我们等了很久他也没来，___就先走了。","p":"wǒmen děng le hěn jiǔ tā yě méilái, yúshì jiù xiān zǒu le.","o":["于是","由于","即使","无论"],"a":0,"e":"Việc tiếp theo: 于是."},{"q":"他每天熬夜，___生病了。","p":"tā měitiān áoyè, jiéguǒ shēngbìng le.","o":["结果","由于","既然","哪怕"],"a":0,"e":"Kết quả không mong muốn: 结果."}]},{"lv":5,"id":"h5-yiwei","name":"以…为… và 把…当作/看作","zh":"以 A 为 B / 把 A 当作 B","use":"以 A 为 B (văn viết) = lấy A làm B, coi A là B. 把 A 当作/看作 B = xem A như B.","form":[["以 + A + 为 + B","以学生为中心"],["把 + A + 当作/看作/当成 + B","把他当作朋友"]],"tips":["Cụm hay gặp: 以…为主 (lấy… làm chính), 以…为例 (lấy… làm ví dụ), 以…为荣 (lấy… làm vinh dự)."],"eg":[["这家公司以年轻人为主要客户。","zhèjiā gōngsī yǐ niánqīngrén wèi zhǔyào kèhù.","Công ty này lấy người trẻ làm khách hàng chính.",["这家","公司","以","年轻人","为","主要","客户","。"]],["我们以这个问题为例来说明。","wǒmen yǐ zhège wèntí wèi lìlái shuōmíng.","Chúng ta lấy vấn đề này làm ví dụ để giải thích.",["我们","以","这个","问题","为","例来","说明","。"]],["她一直把工作当作生活的一部分。","tā yīzhí bǎ gōngzuò dàngzuò shēnghuó de yībùfèn.","Cô ấy luôn coi công việc là một phần của cuộc sống.",["她","一直","把","工作","当作","生活","的","一部分","。"]]],"fix":["以学生为了中心。","以学生为中心。","Cấu trúc là 以…为….","yǐ xuésheng wèi zhōngxīn."],"ex":[{"q":"这次活动以环保___主题。","p":"zhècì huódòng yǐ huánbǎo wèi zhǔtí.","o":["为","作","是","当"],"a":0,"e":"以…为…."},{"q":"父母都以孩子的成功___荣。","p":"fùmǔ dōu yǐ háizi de chénggōng wèiróng.","o":["为","是","当","作为"],"a":0,"e":"以…为荣."},{"q":"他把我___作亲妹妹一样照顾。","p":"tā bǎ wǒ dàngzuò qīn mèimei yīyàng zhàogu.","o":["当","为","成","是"],"a":0,"e":"把…当作."},{"q":"我们的饮食应该以蔬菜为___。","p":"wǒmen de yǐnshí yīnggāi yǐ shūcài wéizhǔ.","o":["主","多","好","要"],"a":0,"e":"以…为主."}]},{"lv":5,"id":"h5-yuqi","name":"So sánh lựa chọn: 与其…不如, 宁可…也不","zh":"与其 / 不如 / 宁可 / 也不","use":"与其 A，不如 B = thà B còn hơn A (chọn B). 宁可 A，也不 B = thà A chứ không B (chấp nhận A bất lợi để tránh B).","form":[["与其 + A，不如 + B","与其在家等，不如出去找"],["宁可 + A，也不/也要 + B","宁可走路，也不坐他的车"]],"tips":[],"eg":[["与其抱怨，不如想办法解决问题。","yǔqí bàoyuàn, bùrú xiǎng bànfǎ jiějuéwèntí.","Thay vì than phiền, chi bằng nghĩ cách giải quyết vấn đề.",["与其","抱怨","，","不如","想","办法","解决问题","。"]],["我宁可少赚点儿钱，也不想天天加班。","wǒ nìngkě shǎo zhuàn diǎnér qián, yě bùxiǎng tiāntiān jiābān.","Tôi thà kiếm ít tiền một chút còn hơn ngày nào cũng tăng ca.",["我","宁可","少","赚","点儿","钱","，","也","不想","天天","加班","。"]],["与其坐出租车，不如坐地铁，又快又便宜。","yǔqí zuò chūzūchē, bùrú zuòdìtiě, yòu kuài yòu piányi.","Đi taxi chẳng bằng đi tàu điện ngầm, vừa nhanh vừa rẻ.",["与其","坐","出租车","，","不如","坐地铁","，","又","快","又","便宜","。"]]],"fix":["与其在家睡觉，宁可出去走走。","与其在家睡觉，不如出去走走。","与其 đi với 不如.","yǔqí zàijiā shuìjiào, bùrú chūqù zǒuzǒu."],"ex":[{"q":"与其在这里浪费时间，___早点儿回家。","p":"yǔqí zài zhèlǐ làngfèishíjiān, bùrú zǎodiǎnér huíjiā.","o":["不如","宁可","也不","还是"],"a":0,"e":"与其…不如."},{"q":"他宁可饿着，___吃不健康的东西。","p":"tā nìngkě è zhe, yě bùchī bù jiànkāng de dōngxi.","o":["也不","不如","就","才"],"a":0,"e":"宁可…也不."},{"q":"___求别人，不如自己动手。","p":"yǔqí qiú biéren, bùrú zìjǐ dòngshǒu.","o":["与其","宁可","即使","虽然"],"a":0,"e":"与其…不如."},{"q":"我___多花点儿钱，也要买质量好的。","p":"wǒ nìngkě duō huādiǎnérqián, yě yào mǎi zhìliàng hǎo de.","o":["宁可","与其","不如","即使是"],"a":0,"e":"宁可…也要."}]},{"lv":5,"id":"h5-zhisuoyi","name":"之所以…是因为…","zh":"之所以 / 是因为","use":"Nêu kết quả trước rồi giải thích nguyên nhân, nhấn mạnh lý do: sở dĩ… là vì…","form":[["S + 之所以 + kết quả，是因为 + nguyên nhân","他之所以成功，是因为很努力"]],"tips":["Khác 因为…所以 (nguyên nhân trước), 之所以 đặt kết quả trước."],"eg":[["我之所以选择这份工作，是因为它很有挑战性。","wǒ zhīsuǒyǐ xuǎnzé zhèfèn gōngzuò, shìyīnwèi tā hěn yǒu tiǎozhànxìng.","Sở dĩ tôi chọn công việc này là vì nó rất thử thách.",["我","之所以","选择","这份","工作","，","是因为","它","很","有","挑战性","。"]],["这家店之所以受欢迎，是因为服务好。","zhèjiā diàn zhīsuǒyǐ shòuhuānyíng, shìyīnwèi fúwù hǎo.","Cửa hàng này sở dĩ được ưa chuộng là vì phục vụ tốt.",["这家","店","之所以","受欢迎","，","是因为","服务","好","。"]],["他之所以迟到，是因为路上出了事故。","tā zhīsuǒyǐ chídào, shìyīnwèi lùshang chū le shìgù.","Anh ấy sở dĩ đến muộn là vì trên đường có tai nạn.",["他","之所以","迟到","，","是因为","路上","出","了","事故","。"]]],"fix":["之所以他没来，所以生病了。","他之所以没来，是因为生病了。","之所以 đi với 是因为.","tā zhīsuǒyǐ méi lái, shìyīnwèi shēngbìng le."],"ex":[{"q":"我之所以喜欢这座城市，___这里的人很热情。","p":"wǒ zhīsuǒyǐ xǐhuan zhèzuò chéngshì, shìyīnwèi zhèlǐ de rén hěn rèqíng.","o":["是因为","所以","因此","由于是"],"a":0,"e":"之所以…是因为."},{"q":"他___能考上大学，是因为一直坚持学习。","p":"tā zhīsuǒyǐ néng kǎoshàng dàxué, shìyīnwèi yīzhí jiānchí xuéxí.","o":["之所以","所以","因此","于是"],"a":0,"e":"之所以…是因为."},{"q":"这个产品之所以卖得好，是因为价格___。","p":"zhège chǎnpǐn zhīsuǒyǐ màidé hǎo, shìyīnwèi jiàgéhélǐ.","o":["合理","合理的","很合理了","合理地"],"a":0,"e":"是因为 + mệnh đề."},{"q":"他之所以这样做，是___保护大家。","p":"tā zhīsuǒyǐ zhèyàng zuò, shì wèile bǎohù dàjiā.","o":["为了","因为了","由于","所以"],"a":0,"e":"Mục đích: 是为了."}]},{"lv":5,"id":"h5-buzhi","name":"Tăng tiến nâng cao: 不仅…还/甚至, 何况, 况且","zh":"不仅 / 甚至 / 何况 / 况且","use":"不仅…而且/还/也… = không chỉ… mà còn… 甚至 = thậm chí (đẩy mức độ lên cao hơn). 何况 = huống chi (đã A thì B càng hiển nhiên). 况且 = hơn nữa (thêm lý do).","form":[["不仅 + A，而且/还 + B","不仅便宜，而且质量好"],["A，甚至 + B","他很忙，甚至周末也加班"],["A 都…，何况 B 呢？","大人都搬不动，何况孩子呢？"]],"tips":[],"eg":[["这本书不仅内容丰富，而且语言简单。","zhè běnshū bùjǐn nèiróngfēngfù, érqiě yǔyán jiǎndān.","Cuốn sách này không chỉ nội dung phong phú mà ngôn ngữ còn đơn giản.",["这","本书","不仅","内容丰富","，","而且","语言","简单","。"]],["他紧张得甚至忘了自己的名字。","tā jǐnzhāng de shènzhì wàng le zìjǐ de míngzi.","Anh ấy căng thẳng đến mức thậm chí quên cả tên mình.",["他","紧张","得","甚至","忘","了","自己","的","名字","。"]],["这个问题专家都解决不了，何况我们呢？","zhège wèntí zhuānjiā dōu jiějuébùliǎo, hékuàng wǒmen ne?","Vấn đề này chuyên gia còn không giải quyết được, huống chi chúng ta?",["这个","问题","专家","都","解决不了","，","何况","我们","呢","？"]]],"fix":["大人都不懂，况且孩子呢？","大人都不懂，何况孩子呢？","Huống chi dùng 何况.","dàren dōu bù dǒng, hékuàng háizi ne?"],"ex":[{"q":"他不仅会说英语，___会说法语。","p":"tā bùjǐn huì shuō yīngyǔ, háihuì shuō fǎyǔ.","o":["还","甚至还是","就","才"],"a":0,"e":"不仅…还."},{"q":"这么简单的题，小学生都会，___大学生呢？","p":"zhème jiǎndān de tí, xiǎoxuéshēng dūhuì, hékuàng dàxuéshēng ne?","o":["何况","况且","甚至","而且"],"a":0,"e":"何况."},{"q":"天已经黑了，___又下着雨，你别走了。","p":"tiān yǐjīng hēi le, kuàngqiě yòu xiàzheyǔ, nǐbié zǒu le.","o":["况且","何况","甚至","因此"],"a":0,"e":"Thêm lý do: 况且."},{"q":"他太累了，___站着都能睡着。","p":"tātàilèi le, shènzhì zhàn zhe dōu néng shuìzháo.","o":["甚至","何况","况且","与其"],"a":0,"e":"Thậm chí: 甚至."}]},{"lv":5,"id":"h5-duilai","name":"Nêu góc nhìn: 对…来说, 在…看来, 就…而言","zh":"对…来说 / 在…看来 / 就…而言","use":"Dùng để nêu đối tượng hoặc góc độ đánh giá. 对…来说 = đối với… mà nói. 在…看来 = theo cách nhìn của… 就…而言 (văn viết) = xét về….","form":[["对 + người/vật + 来说，…","对我来说，健康最重要"],["在 + người + 看来，…","在他看来，这不是问题"],["就 + phương diện + 而言，…","就质量而言，这个更好"]],"tips":[],"eg":[["对年轻人来说，买房压力很大。","duì niánqīngrén láishuō, mǎifáng yālì hěndà.","Đối với người trẻ mà nói, áp lực mua nhà rất lớn.",["对","年轻人","来说","，","买房","压力","很大","。"]],["在我看来，这个计划还需要修改。","zàiwǒkànlái, zhège jìhuà hái xūyào xiūgǎi.","Theo tôi, kế hoạch này vẫn cần sửa.",["在我看来","，","这个","计划","还","需要","修改","。"]],["就价格而言，这款手机很有优势。","jiù jiàgé éryán, zhè kuǎn shǒujī hěn yǒu yōushì.","Xét về giá, mẫu điện thoại này rất có ưu thế.",["就","价格","而言","，","这","款","手机","很","有","优势","。"]]],"fix":["对我来看，这很难。","对我来说，这很难。","Cố định: 对…来说 / 在…看来.","duì wǒ láishuō, zhè hěn nán."],"ex":[{"q":"对初学者___，汉字是最难的。","p":"duì chūxuézhě láishuō, hànzì shì zuìnán de.","o":["来说","看来","而言是","说来"],"a":0,"e":"对…来说."},{"q":"在很多人___，成功就是赚很多钱。","p":"zài hěnduō rén kànlai, chénggōng jiùshì zhuàn hěnduō qián.","o":["看来","来说","而言","说"],"a":0,"e":"在…看来."},{"q":"___环境而言，这个城市比较适合居住。","p":"jiù huánjìng éryán, zhège chéngshì bǐjiào shìhé jūzhù.","o":["就","对","在","把"],"a":0,"e":"就…而言."},{"q":"这个工作对我___，是一个很好的机会。","p":"zhège gōngzuò duì wǒ láishuō, shì yígè hěn hǎo de jīhuì.","o":["来说","看来","而言","来看"],"a":0,"e":"对…来说."}]},{"lv":5,"id":"h5-mudi","name":"Mục đích: 为了, 以便, 好让","zh":"为了 / 以便 / 好 / 让","use":"为了 + mục đích (thường đứng đầu câu). 以便 (văn viết) = để tiện cho. 好 + V (văn nói) = để có thể.","form":[["为了 + mục đích，S + V","为了提高汉语水平，他每天练习"],["A，以便 + B","请留下电话，以便我们联系您"],["A，好 + V","你把地址写下来，我好去找你"]],"tips":["因为 nói nguyên nhân, 为了 nói mục đích; không dùng lẫn."],"eg":[["为了身体健康，他戒了烟。","wèile shēntǐjiànkāng, tājiè le yān.","Vì sức khỏe, anh ấy đã bỏ thuốc lá.",["为了","身体健康","，","他戒","了","烟","。"]],["请提前预订，以便我们安排座位。","qǐng tíqián yùdìng, yǐbiàn wǒmen ānpái zuòwèi.","Xin vui lòng đặt trước để chúng tôi tiện sắp xếp chỗ ngồi.",["请","提前","预订","，","以便","我们","安排","座位","。"]],["你早点儿告诉我，我好做准备。","nǐ zǎodiǎnér gàosu wǒ, wǒ hǎo zuò zhǔnbèi.","Bạn báo sớm cho tôi để tôi chuẩn bị.",["你","早点儿","告诉","我","，","我","好","做","准备","。"]]],"fix":["因为通过考试，他每天学习。","为了通过考试，他每天学习。","Mục đích dùng 为了.","wèile tōngguò kǎoshì, tā měitiān xuéxí."],"ex":[{"q":"___赶上飞机，他早上五点就起床了。","p":"wèile gǎnshàng fēijī, tā zǎoshang wǔdiǎn jiù qǐchuáng le.","o":["为了","因为","由于","既然"],"a":0,"e":"Mục đích: 为了."},{"q":"请把文件发给我，___我今天看完。","p":"qǐng bǎ wénjiàn fāgěi wǒ, yǐbiàn wǒ jīntiān kàn wán.","o":["以便","因此","于是","甚至"],"a":0,"e":"以便."},{"q":"你把门开着，我___进来。","p":"nǐ bǎmén kāizhe, wǒ hǎo jìnlái.","o":["好","好的","为","以免"],"a":0,"e":"好 + V."},{"q":"他这样做是___大家好。","p":"tā zhèyàng zuò shì wèile dàjiā hǎo.","o":["为了","因为","由于","对于"],"a":0,"e":"是为了…."}]},{"lv":6,"id":"h6-guran","name":"固然…但/也…","zh":"固然 / 但 / 也","use":"固然 thừa nhận một sự thật (đúng là…), rồi chuyển ý hoặc bổ sung điều quan trọng hơn ở vế sau.","form":[["A 固然 + nhận định，但(是)/可是 + B","成绩固然重要，但健康更重要"],["A 固然 + nhận định，B 也 + nhận định","去固然好，不去也没关系"]],"tips":[],"eg":[["钱固然重要，但不是生活的全部。","qián gùrán zhòngyào, dàn búshì shēnghuó de quánbù.","Tiền đúng là quan trọng, nhưng không phải tất cả cuộc sống.",["钱","固然","重要","，","但","不是","生活","的","全部","。"]],["这个方法固然有效，可是成本太高。","zhège fāngfǎ gùrán yǒuxiào, kěshì chéngběn tàigāo.","Phương pháp này đúng là hiệu quả, nhưng chi phí quá cao.",["这个","方法","固然","有效","，","可是","成本","太高","。"]],["能参加固然好，不能参加也没关系。","néng cānjiā gùrán hǎo, bùnéng cānjiā yě méiguānxi.","Tham gia được thì tốt, không tham gia được cũng không sao.",["能","参加","固然","好","，","不能","参加","也","没关系","。"]]],"fix":["固然他很聪明，所以考得好。","他固然很聪明，但也需要努力。","固然 dẫn tới vế chuyển ý.","tā gùrán hěn cōngming, dàn yě xūyào nǔlì."],"ex":[{"q":"经验固然重要，___态度也不能忽视。","p":"jīngyàn gùrán zhòngyào, dàn tàidu yě bùnéng hūshì.","o":["但","所以","因此","于是"],"a":0,"e":"固然…但."},{"q":"自己做饭___麻烦，但是比较健康。","p":"zìjǐ zuòfàn gùrán máfan, dànshì bǐjiào jiànkāng.","o":["固然","即使","既然","与其"],"a":0,"e":"Thừa nhận: 固然."},{"q":"有人帮忙固然好，没人帮忙我们___能完成。","p":"yǒurén bāngmáng gùrán hǎo, méi rén bāngmáng wǒmen yě néng wánchéng.","o":["也","就","才","还是"],"a":0,"e":"固然…也."},{"q":"价格低___吸引人，但质量才是关键。","p":"jiàgédī gùrán xīyǐn rén, dàn zhìliàng cái shì guānjiàn.","o":["固然","甚至","何况","以便"],"a":0,"e":"固然 thừa nhận ưu điểm."}]},{"lv":6,"id":"h6-yimian","name":"Tránh hậu quả: 以免, 免得, 省得","zh":"以免 / 免得 / 省得","use":"Đặt ở vế sau để nói làm việc A nhằm tránh hậu quả B. 以免 trang trọng; 免得, 省得 dùng trong văn nói.","form":[["A，以免 + hậu quả","请保管好护照，以免丢失"],["A，免得/省得 + hậu quả","多穿点儿，免得感冒"]],"tips":[],"eg":[["开车时不要看手机，以免发生事故。","kāichē shí bùyào kàn shǒujī, yǐmiǎn fāshēng shìgù.","Khi lái xe đừng xem điện thoại để tránh xảy ra tai nạn.",["开车","时","不要","看","手机","，","以免","发生","事故","。"]],["你到了给我打个电话，免得我担心。","nǐ dào le gěi wǒ dǎgè diànhuà, miǎnde wǒ dānxīn.","Đến nơi thì gọi cho tôi kẻo tôi lo.",["你","到","了","给","我","打个","电话","，","免得","我","担心","。"]],["我们直接在网上买吧，省得跑一趟。","wǒmen zhíjiē zài wǎngshàng mǎi ba, shěngde pǎo yītàng.","Mình mua thẳng trên mạng đi, đỡ phải chạy một chuyến.",["我们","直接","在","网上","买","吧","，","省得","跑","一趟","。"]]],"fix":["带上雨伞，以便被雨淋。","带上雨伞，以免被雨淋。","Tránh hậu quả dùng 以免.","dàishàng yǔsǎn, yǐmiǎn bèi yǔlín."],"ex":[{"q":"请仔细检查，___出现错误。","p":"qǐng zǐxìjiǎnchá, yǐmiǎn chūxiàn cuòwù.","o":["以免","以便","为了","于是"],"a":0,"e":"Tránh hậu quả: 以免."},{"q":"你早点儿睡，___明天起不来。","p":"nǐ zǎodiǎnér shuì, miǎnde míngtiān qǐbùlái.","o":["免得","以便","好让","何况"],"a":0,"e":"免得."},{"q":"把重要文件备份一下，___丢失。","p":"bǎ zhòngyàowénjiàn bèifèn yīxià, yǐmiǎn diūshī.","o":["以免","以便","只要","为了"],"a":0,"e":"以免."},{"q":"我自己去吧，___麻烦你。","p":"wǒ zìjǐ qù ba, shěngde máfan nǐ.","o":["省得","以便","甚至","固然"],"a":0,"e":"省得."}]},{"lv":6,"id":"h6-weibi","name":"Phủ định mềm: 未必, 不见得, 不至于","zh":"未必 / 不见得 / 不至于","use":"未必, 不见得 = chưa chắc (phủ định nhẹ, không tuyệt đối). 不至于 = chưa đến mức (sự việc không nghiêm trọng như vậy).","form":[["S + 未必/不见得 + V/adj","贵的东西未必好"],["S + 不至于 + V/adj","他不至于连这个都不知道"]],"tips":[],"eg":[["有钱的人未必幸福。","yǒuqián de rén wèibì xìngfú.","Người có tiền chưa chắc đã hạnh phúc.",["有钱","的","人","未必","幸福","。"]],["他说的不见得是真的。","tā shuō de bùjiànde shì zhēnde.","Điều anh ấy nói chưa chắc là thật.",["他","说","的","不见得","是","真的","。"]],["这点小事不至于让他生气吧。","zhèdiǎn xiǎoshì bùzhìyú ràng tā shēngqì ba.","Chuyện nhỏ này chưa đến mức làm anh ấy giận chứ.",["这点","小事","不至于","让","他","生气","吧","。"]]],"fix":["贵的东西未必不好的。","贵的东西未必好。","未必 + tính từ, không thêm 的 cuối.","guì de dōngxi wèibì hǎo."],"ex":[{"q":"学历高的人___能力强。","p":"xuélì gāo de rén wèibì nénglì qiáng.","o":["未必","不至于","何况","固然"],"a":0,"e":"Chưa chắc: 未必."},{"q":"只是一次考试没考好，___这么难过吧？","p":"zhǐshì yīcì kǎoshì méikǎo hǎo, bùzhìyú zhème nánguò ba?","o":["不至于","未必","不见得","以免"],"a":0,"e":"Chưa đến mức: 不至于."},{"q":"他说明天会下雨，我看___。","p":"tā shuō míngtiān huì xiàyǔ, wǒ kàn bùjiànde.","o":["不见得","不至于","免得","以免"],"a":0,"e":"Chưa chắc (đứng cuối): 不见得."},{"q":"便宜的东西___质量差。","p":"piányi de dōngxi bùjiànde zhìliàng chà.","o":["不见得","不至于是","以免","省得"],"a":0,"e":"Chưa chắc: 不见得."}]},{"lv":6,"id":"h6-yidan","name":"Giả định một khi: 一旦…就…","zh":"一旦 / 就","use":"一旦 = một khi, hễ (giả định một việc xảy ra, thường dẫn đến hậu quả quan trọng).","form":[["一旦 + điều kiện，(S) + 就 + kết quả","一旦决定了，就不要后悔"]],"tips":[],"eg":[["一旦发现问题，请马上联系我们。","yīdàn fāxiàn wèntí, qǐng mǎshàng liánxì wǒmen.","Một khi phát hiện vấn đề, xin liên hệ ngay với chúng tôi.",["一旦","发现","问题","，","请","马上","联系","我们","。"]],["习惯一旦养成，就很难改变。","xíguàn yīdàn yǎngchéng, jiù hěn nán gǎibiàn.","Thói quen một khi đã hình thành thì rất khó thay đổi.",["习惯","一旦","养成","，","就","很","难","改变","。"]],["一旦错过这个机会，你会后悔的。","yīdàn cuòguò zhège jīhuì, nǐ huì hòuhuǐ de.","Một khi bỏ lỡ cơ hội này, bạn sẽ hối hận.",["一旦","错过","这个","机会","，","你","会","后悔","的","。"]]],"fix":["一旦下雨，比赛才取消。","一旦下雨，比赛就取消。","一旦 đi với 就.","yīdàn xiàyǔ, bǐsài jiù qǔxiāo."],"ex":[{"q":"一旦开始，___不能停下来。","p":"yīdàn kāishǐ, jiù bùnéng tíngxiàlái.","o":["就","才","也","都"],"a":0,"e":"一旦…就."},{"q":"信任___失去，就很难找回来。","p":"xìnrèn yīdàn shīqù, jiù hěn nán zhǎo huílai.","o":["一旦","即使","与其","固然"],"a":0,"e":"一旦."},{"q":"___出现紧急情况，请拨打这个电话。","p":"yīdàn chūxiàn jǐnjíqíngkuàng, qǐng bōdǎ zhège diànhuà.","o":["一旦","宁可","何况","未必"],"a":0,"e":"Một khi: 一旦."},{"q":"这种病一旦发现，___要及时治疗。","p":"zhèzhǒng bìng yīdàn fāxiàn, jiùyào jíshí zhìliáo.","o":["就","才","还","又"],"a":0,"e":"一旦…就."}]},{"lv":6,"id":"h6-feibuke","name":"Nhất định phải: 非…不可, 不得不, 只好","zh":"非…不可 / 不得不 / 只好","use":"非…不可 = nhất định phải (ý chí mạnh hoặc chắc chắn xảy ra). 不得不 = buộc phải (không muốn nhưng phải). 只好 = đành phải (không còn cách khác).","form":[["S + 非 + V + 不可","这本书我非买不可"],["S + 不得不 + V","因为下雨，我们不得不取消活动"],["S + 只好 + V","没有车了，我只好走回去"]],"tips":[],"eg":[["这件事你非去不可。","zhèjiàn shì nǐ fēiqùbùkě.","Việc này bạn nhất định phải đi.",["这件","事","你","非去不可","。"]],["由于预算不够，公司不得不推迟计划。","yóuyú yùsuàn bùgòu, gōngsī bùdébù tuīchí jìhuà.","Do ngân sách không đủ, công ty buộc phải hoãn kế hoạch.",["由于","预算","不够","，","公司","不得不","推迟","计划","。"]],["商店关门了，我们只好明天再来。","shāngdiàn guānmén le, wǒmen zhǐhǎo míngtiān zài lái.","Cửa hàng đóng cửa rồi, chúng ta đành mai lại đến.",["商店","关门","了","，","我们","只好","明天","再","来","。"]]],"fix":["这个问题非解决不。","这个问题非解决不可。","Cấu trúc đầy đủ là 非…不可.","zhège wèntí fēi jiějué bùkě."],"ex":[{"q":"你这样下去，身体非出问题___。","p":"nǐ zhèyàng xiàqù, shēntǐ fēichū wèntí bùkě.","o":["不可","不行了","不得","不能"],"a":0,"e":"非…不可."},{"q":"最后一班车也走了，我们___打车回家。","p":"zuìhòu yī bānchē yě zǒu le, wǒmen zhǐhǎo dǎchē huíjiā.","o":["只好","非","何况","固然"],"a":0,"e":"Đành phải: 只好."},{"q":"工作太多，他___周末加班。","p":"gōngzuò tài duō, tā bùdébù zhōumò jiābān.","o":["不得不","非","不至于","未必"],"a":0,"e":"Buộc phải: 不得不."},{"q":"这部电影太好看了，我___再看一遍不可。","p":"zhèbù diànyǐng tài hǎokàn le, wǒ fēi zài kànyībiàn bùkě.","o":["非","只好","不得不","一旦"],"a":0,"e":"非…不可."}]}];
